(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["audio"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-predgen-accelerated-inference-of-lar-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-1\">一 · 现场：一句“帮我订明天下午的会议室”之后的三百毫秒空档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-2\">二 · 旧方案：等封口、整段预填、逐 token 解码的串行三段式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-3\">三 · 为什么非改不可：解码项主导，且与输入时间窗完全解耦</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-4\">四 · 代价账：旧栈在 Blackwell 档位上的三笔开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-5\">五 · 一个具体请求的旧栈时间线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-6\">六 · 失败模式的伏笔：为什么旧栈的“保守”其实是对的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-7\">七 · 输入未定时就开算：PredGen 的失效边界与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-8\">八 · 负载的四个可测维度：前缀长度、到达节奏、并发与批形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-9\">九 · SLO 的分解：首包延迟是唯一硬指标，其余是软约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-10\">十 · 长尾从哪里来：识别纠错、触发抖动与批内错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-11\">十一 · 负载反过来限制方案：K 的上界由并发与显存共同钉死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-12\">十二 · 可核查的测量口径清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-13\">十三 · 方案对负载的反向塑造：从“来什么算什么”到“按窗口排布”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-14\">十四 · 推测路径上的核心算子与数据流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-15\">十五 · 数据类型选择：FP16/BF16、FP8 与 NVFP4</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-16\">十六 · 累加精度与误差传播</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-17\">十七 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-18\">十八 · 校验环节的数值一致性要求</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-19\">十九 · 推测命中的数值边界：FP8/NVFP4 下校验为何先于算力失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-20\">二十 · 显存账本的三条腿：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-21\">二十一 · 分页与碎片：为什么推测分支最怕外部碎片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-22\">二十二 · 压缩与复用：命中即复用，复用即省带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-23\">二十三 · 卸载：把冷 KV 挪出 HBM 的边界条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-24\">二十四 · 可复算的显存预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-25\">二十五 · 带宽瓶颈落在哪：一次解码步的读写剖面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-26\">二十六 · 推测窗口的显存账本与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-27\">二十七 · 推测请求在连续批处理里的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-28\">二十八 · chunked prefill 与增量预填的叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-29\">二十九 · 优先级、抢占与 KV 的回收边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-30\">三十 · 分离式预填/解码下的推测归属</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-31\">三十一 · 尾延迟的压法：从分位数到触发阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-32\">三十二 · 推测窗口与批调度的耦合边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-33\">三十三 · 切分策略：从单卡放不下到多卡并行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-34\">三十四 · NVLink 5 与 NVSwitch：域内带宽的物理边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-35\">三十五 · All-to-All 与 EP：路由不确定性的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-36\">三十六 · PP 与 DP：气泡与复制的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-37\">三十七 · NIXL 传输与分离式部署的通信面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-38\">三十八 · 通信何时成为瓶颈：三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-39\">三十九 · 切分方式决定推测窗口能否被并行摊薄</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-40\">四十 · 精度塌陷：校验通过但输出已偏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-41\">四十一 · OOM：KV 碎片与推测预留的叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-42\">四十二 · 批抖动：命中率随 batch 位置漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-43\">四十三 · 尾延迟：回退重算的长尾</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-44\">四十四 · 静默降级：收益消失而不报警</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-45\">四十五 · 推测失效的五类现场：从命中率塌陷到静默降级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-46\">四十六 · 口径先行：这份材料能支撑什么、不能支撑什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-47\">四十七 · 硬件档位：Blackwell 上哪些量会变、哪些不会变</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-48\">四十八 · batch 与并发：延迟收益在批处理下会被稀释</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-49\">四十九 · 指标口径：TTFT、TPOT、吞吐、显存、功耗各自量的是什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-50\">五十 · 哪些提升不可比：四类常见的错误外推</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-51\">五十一 · 把数字读成决策：需要补测的最小实验集</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-52\">五十二 · 迁移到非语音自回归模型：时间冗余从哪来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-53\">五十三 · 校验语义的边界：确定性前向是硬前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-54\">五十四 · 与分离式预填/解码和连续批处理的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-55\">五十五 · 规模上限：命中率随前缀长度衰减</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-56\">五十六 · 不适用的场景与判断清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-predgen-accelerated-inference-of-lar-2025-sec-57\">五十七 · 迁移到非流式负载与低命中率场景时的失效边界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:559px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 559.4 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"477.4\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">语音识别流式输出增量文本，进入输入缓冲并按时间片切分为当前前缀。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"477.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">推测触发器在当前前缀上启动一次短程自回归解码，生成候选续写及其 KV。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"477.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用户继续说话，缓冲追加新 token，引擎仅对新增部分做增量预填。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"477.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">最终输入确定后，校验器比对推测前缀与真实前缀的公共长度。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"477.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">命中部分直接复用已生成 token 与 KV，未命中部分从分歧点回退重…</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"477.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码继续至结束，首包提前发出，语音合成随即启动。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-1\">一 · 现场：一句“帮我订明天下午的会议室”之后的三百毫秒空档</h3>\n<p>设想一个跑在 GB200 NVL72 上的实时语音助手：用户对着手机说“帮我订明天下午的会议室，最好靠窗”，语音识别流在用户说到“会议室”时已经吐出前十几个词，但系统并不发声。它要等 VAD 判定话尾、识别流封口、把完整前缀送进预填，再从第一个 token 开始逐位自回归解码，直到攒够第一个可送去 TTS 的语义片段。用户听到的，是说完之后一段可感知的静默。这段静默不是网络抖动，也不是 TTS 启动慢，而是被解码步数直接定价的：首包延迟 ≈ 预填时间 + k 步解码时间 + 声码器首帧时间，其中 k 由“第一个可发声单元需要多少个 token”决定，而每一步解码都要把全部权重从 HBM 拉进 SM、走一遍完整前向。在百亿级以上的模型上，单步解码的权重带宽代价远大于其计算量，解码阶段天然是带宽受限而非算力受限的，这就是空档的物理来源。</p>\n<p>更糟的是，这段时间里加速器的算力大量空转。预填阶段是计算密集的，能打满 tensor core；一旦进入逐 token 解码，矩阵乘退化成窄向量乘宽权重，SM 占用率掉下来，HBM 带宽却被打满。用户说话的那几秒，恰恰是整条推理栈最闲的几秒——输入还没封口，不能预填；不预填，就没有 KV；没有 KV，就无法解码。传统栈把“用户说话”和“模型计算”严格串行成两个阶段，时间冗余被整段浪费掉。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-2\">二 · 旧方案：等封口、整段预填、逐 token 解码的串行三段式</h3>\n<p>论文之前的主流做法可以概括为三段式串行流水。第一段，流式 ASR 持续输出增量文本，但推理侧只做缓冲不做计算，直到端点检测触发。第二段，把完整前缀一次性送入引擎做预填，生成整段 KV cache；这一步的代价与前缀长度呈超线性关系（注意力部分的 KV 读写随长度增长），长指令下预填本身就能吃掉可观时间。第三段，从零开始自回归解码，每步采样一个 token、追加进 KV、再前向一次，直到凑够首包。</p>\n<p>这套流程的代价结构很清晰：首包延迟由“封口等待 + 预填 + k 步解码”三项相加，其中封口等待由用户语速决定、不可压缩，预填随前缀变长而增长，解码项则随模型规模与 k 线性增长。吞吐侧的问题在于解码阶段的批利用率——单会话解码的 batch 极小，权重读取被摊薄得很差；显存侧则是 KV cache 在封口后才开始分配，长前缀一次性写入造成瞬时峰值。对在线服务而言，这意味着为了守住首包 SLO，只能靠堆副本、堆并发来掩盖单请求的解码长尾，单位算力的有效吞吐被拉低。</p>\n<p>工程上曾有几条局部缓解路径，但都没触及根因。其一是流式预填的分块化：把前缀按 chunk 送入，边到边算 KV，减少封口后的预填尖峰——它压缩了第二段，却完全没有动第三段，解码步数一步没少。其二是把首包做短，让模型先吐一个短促的应答词再展开——这改变了输出内容策略，不是加速。其三是投机解码，用草稿模型或额外头预生成候选 token 再由主模型并行校验——它确实压缩了解码步数，但触发时机仍在“输出后”，即必须等真实前缀确定、解码已经开始，才能 speculate；用户说话的那段窗口依旧空着。换句话说，旧栈的所有加速都发生在“输入已封口”之后，而空档的大头恰恰在封口之前。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-3\">三 · 为什么非改不可：解码项主导，且与输入时间窗完全解耦</h3>\n<p>把首包延迟拆开看，设封口等待为 <span>W</span>、预填为 <span>F</span>、单步解码为 <span>d</span>、首包所需 token 数为 <span>k</span>，则 <span>L = W + F + k·d</span>。在模型规模上去之后，<span>d</span> 由权重带宽决定而几乎不随 batch 缩小，<span>k·d</span> 往往成为三项中的主导项；而 <span>W</span> 是用户说话的自然时长，与算力无关。旧栈的结构性缺陷就在于：<span>k·d</span> 这段本可以在 <span>W</span> 内并行推进的工作，被硬生生排到了 <span>W</span> 之后。要压 <span>L</span>，要么减 <span>k</span>（改输出策略，有损），要么减 <span>d</span>（换硬件/量化，有边界），要么把 <span>k·d</span> 的一部分挪进 <span>W</span> 里——最后这条正是 PredGen 的切入点，也是旧栈无法通过调参解决的问题。</p>\n<p>论文给出的收益刻画是：</p>\n<div class=\"formula\">$$L_{\\text{eff}}=\\frac{T_{\\text{decode}}}{1+\\alpha\\cdot h},\\quad h=\\frac{|P_{\\text{spec}}\\cap P_{\\text{final}}|}{|P_{\\text{spec}}|}$$</div>\n<p>其中 <span>h</span> 是推测前缀与最终前缀的公共比例，<span>α</span> 表征推测长度带来的可复用解码步数占比。这个式子把工程矛盾摊在明面上：收益线性于命中率，而命中率由流式识别的稳定性决定，不由模型能力决定。举例来说，用户说“帮我订明天下午三点……”时，ASR 在“明天下午”处给出前缀，系统据此推测出“三点”“的会议室”等候选；若用户实际说的是“明天下午四点”，则推测在时间实体处分歧，公共前缀只到“明天下午”，命中部分被截断，后续全部回退重算——冗余算力不但没换来延迟收益，反而因为多做了一次预填与解码而抬高了首包时间。这就是旧栈不敢做输入时推测的原因：没有校验与 KV 复用机制，任何提前计算都是赌博。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-4\">四 · 代价账：旧栈在 Blackwell 档位上的三笔开销</h3>\n<p>把旧栈放到 B200/B300 这一档硬件上看，三笔代价各自有明确的物理落点。第一笔是解码阶段的带宽账：逐 token 解码每步都要把参与计算的权重从 HBM 搬到 SM，SM100 的 HBM 容量与带宽虽然宽裕，但单请求解码的算术强度极低，带宽被打满而 tensor core 闲置，tcgen05 的 MMA 吞吐在 decode 形态下根本喂不饱。第二笔是 KV 显存账：封口后整段前缀一次性预填，KV 在瞬时被写满，长对话下 KV 占用随前缀线性上涨，挤占并发会话的可用显存，逼得批调度只能保守排布。第三笔是空转账：用户说话的数秒内，预填引擎无事可做、解码引擎无 KV 可用，整机功耗花在等端点检测上，单位请求的算力浪费率居高不下。</p>\n<p>这三笔账在分离式预填/解码架构下并不会自动消失。PD 分离把预填与解码拆到不同实例，改善的是批内资源匹配，但“输入未封口则无法预填”这一约束依旧成立——预填实例在用户说话期间同样闲置。NIXL 之类的 KV 传输通道解决的是 KV 在实例间搬运的效率，解决不了“KV 还没被算出来”的问题。因此旧栈的痛点不是某个组件的效率问题，而是流水线相位与用户说话节奏的错配：计算资源的时间窗与输入到达的时间窗没有重叠。要改，就必须让引擎在输入尚未确定时就开始产出可复用的中间状态，并且具备在输入翻转时安全丢弃的能力。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-5\">五 · 一个具体请求的旧栈时间线</h3>\n<p>取一个具体例子：用户说一句约四秒的话，ASR 在第二秒末已给出足够长的前缀，首包需要 <span>k</span> 个 token 才能拼出可发声片段。旧栈的时间线是：0–4 秒纯等待，第 4 秒端点检测封口，第 4 秒起做整段预填，预填完成后从第 0 个 token 开始解码 <span>k</span> 步，首包在 4 秒之后若干百毫秒才发出。整条时间线上，前四秒的加速器只承担了 ASR 的轻量计算，推理引擎处于空载。若把这段窗口利用起来，在第二秒末以当时前缀做一次短程推测、生成候选 token 及其 KV，并在后续增量到达时只对新 token 做增量预填，那么封口时校验器只需比对公共前缀：命中部分直接复用，解码从第 <span>k+1</span> 步继续，首包的等待被压到“封口 + 校验 + 少量补算”。</p>\n<p>这条时间线也暴露了旧栈在批调度上的连锁代价。为了守住首包 SLO，服务端必须按最坏情况（长前缀、长解码）预留副本，导致平均利用率低；连续批处理在解码阶段能拼批，但拼进来的是同样处于 decode 形态的请求，带宽依旧是被摊薄的那一项。真正能改善带宽账的，是把一部分解码工作搬到预填形态里去——预填是计算密集的，能打满 tensor core，而输入时推测恰好把解码步数转成了可在说话窗口内完成的预填式前向。这是旧栈结构上做不到、也是本工作非改不可的根本理由：不是某个 kernel 慢，而是相位错配让整段算力窗口被浪费。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-6\">六 · 失败模式的伏笔：为什么旧栈的“保守”其实是对的</h3>\n<p>旧栈选择串行并非工程懒惰，而是因为提前计算在没有校验机制时是不安全的。流式识别会纠错：用户说到一半改口、ASR 在后续增量中修正前面的词，都会让已算出的 KV 对应一个不再成立的前缀。若直接把推测结果拼进最终输出，输出分布就偏离了原模型；若在温度采样下复用推测 token 而不保持随机数状态一致，采样轨迹同样会偏。旧栈用“等封口”换取了确定性，代价就是那段空档。这也解释了为什么输入时推测必须配三件套：增量预填只算新增 token（代价与新增量成正比而非与总前缀成正比）、最长公共前缀校验（命中 k 个则复用其 KV 与输出，分歧点之后全部丢弃）、以及回退重算路径。缺任何一件，提前计算就从加速变成污染。</p>\n<p>由此可以给出一个工程判断：输入时推测的净收益不是模型属性，而是“识别稳定性 × 推测长度 × 硬件档位”的联合函数。识别纠错率高的语种与场景，命中率被压低，长推测反而因回退重算拖慢首包；推测长度过短则收益不足以覆盖校验与增量预填的固定开销。旧栈的串行三段式在这些变量面前是稳健的，因为它不赌；PredGen 的整套机制，本质上是用一套可验证、可回退的契约，把“赌”变成“可结算的预计算”。这套契约在 Blackwell 上的落地形态——KV 复用如何与 TMEM、2-SM MMA 的预填形态对齐，增量预填如何在 NVFP4/FP8 下保持校验所需的数值一致性——才是决定它能否在在线服务里守住 SLO 的关键，而这需要按具体档位实测，材料本身并未给出定量边界。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-7\">七 · 输入未定时就开算：PredGen 的失效边界与系统代价</h3>\n<p>把 PredGen 放进一个真实的在线语音客服场景，痛点立刻显形：用户对着手机说“帮我查一下上周三从虹桥到北京的那班……”话还没说完，ASR 增量文本已经吐出前十几个词，但传统推理栈此时只能空转——它必须等 VAD 判定句尾、拿到完整前缀，才开始预填与逐 token 解码。首包延迟因此被解码步数直接钉死，而解码是串行的，模型再大、卡再多，也压不掉那几十步的串行开销。PredGen 的边界恰恰在这里：它赌的是“用户还在说话”这段窗口足够长，能把一部分解码提前做掉；一旦窗口太短、或 ASR 增量抖动剧烈，提前算的东西就白算。命中率 h 与推测长度 K 共同决定净收益，$$L_{\\text{eff}}=\\frac{T_{\\text{decode}}}{1+\\alpha\\cdot h}$$ 里的 α 实际是“命中部分折算成的有效解码节省”，h 掉下来，分母趋近 1，收益归零，而冗余算力照付。</p>\n<p>失效条件有三类，工程上必须逐条盯住。第一类是识别纠错：流式 ASR 在用户说到一半时经常回改前面的词，比如把“虹桥”先识别成“红桥”再纠正，此时推测前缀与最终前缀在首个 token 就分歧，校验器只能整段丢弃、从真实前缀重算，之前预生成的 KV 全部作废——这是最贵的失败模式，因为它同时浪费了预填算力和 KV 显存。第二类是推测长度失配：K 设得大，低命中率下回退重算的 token 数线性上升，显存里同时挂着推测 KV 与回退后的新 KV，占用翻倍；K 设得小，命中时节省的步数又不足以覆盖触发开销。第三类是采样一致性：温度采样下若随机数状态没有对齐，复用推测 token 会让输出分布偏离原模型，无损加速的前提被破坏，这类问题在 FP8/NVFP4 量化下更隐蔽，因为数值误差会放大前缀比对的歧义。</p>\n<p>系统代价要按 Blackwell 的显存与带宽账来算，而不是只看延迟。增量预填的代价与新增 token 数成正比、与总前缀长度无关，这是它相对整段重算的优势；但推测 KV 是额外驻留的，并发会话数一多，KV 缓存占用随“推测中会话数 × K × 层数 × 头维度”增长，在 GB200 NVL72 这种高并发档位上，KV 碎片与回退频率会直接吃掉批调度的余量。下表把三种典型状态的代价摆在一起：</p>\n<table class=\"mini\"><thead><tr><th>状态</th><th>首包延迟</th><th>冗余算力</th><th>KV 显存</th></tr></thead><tbody><tr><td>高命中、短 K</td><td>明显下降</td><td>低</td><td>基线 + 少量推测 KV</td></tr><tr><td>低命中、长 K</td><td>可能反升</td><td>高，回退重算主导</td><td>推测 KV 与重算 KV 并存，翻倍</td></tr><tr><td>识别抖动、首 token 分歧</td><td>无收益</td><td>全额浪费</td><td>推测 KV 全丢，碎片化</td></tr></tbody></table>\n<p>所以这套方案的工程判断不是“能不能加速”，而是“在什么识别稳定性与并发档位下净收益为正”。触发阈值必须跟 ASR 的增量节奏绑定：停顿检测过早触发，前缀短、推测命中概率低；过晚触发，窗口不够、提前量不足。落地时要把命中率、回退率、单位请求冗余算力作为一等监控指标，与首包延迟分位数一起看——只看延迟会掩盖算力浪费，只看命中率会忽略长 K 在低命中下的反噬。PredGen 的无损性只在“校验严格 + 随机数状态一致”时成立，任何为了压延迟而放宽校验的改动，都会把无损加速变成有偏加速，这在实时 TTS 场景里是不可接受的。</p>\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-8\">八 · 负载的四个可测维度：前缀长度、到达节奏、并发与批形</h3>\n<p>PredGen 的负载不是“一个请求一段文本”，而是一条随时间片增长的识别前缀流。要把它变成可调度对象，必须先把负载拆成四个正交维度，每个维度都有独立的测量口径。第一维是<strong>前缀长度分布</strong>：以语音识别增量文本的 token 数为单位，按时间片记录 <code>len(prefix_t)</code>，统计其分位数而非均值——因为推测触发点由前缀长度决定，均值会掩盖触发时机的离散性。第二维是<strong>增量到达节奏</strong>：相邻两次增量到达的时间间隔 <code>Δτ</code>，以及单次增量携带的 token 数 <code>Δn</code>，二者共同决定增量预填的粒度；测量口径是 <code>Δn/Δτ</code> 的分布，而非总时长。第三维是<strong>并发会话数</strong>：同时在说话、同时在推测、同时在解码的会话分别计数，三者不相等，KV 占用由三者叠加决定。第四维是<strong>批形</strong>：一次前向里被拼进同一 batch 的序列长度向量，因为增量预填的序列长度参差，批内 padding 与变长注意力的实际算力浪费必须单独记账。</p>\n<p>这四个维度不是并列的，而是有因果链：到达节奏决定前缀长度的增长曲线，增长曲线决定推测触发频率，触发频率乘以并发数决定单位时间内的推测次数，推测次数再乘以推测长度 K 决定冗余算力总量。工程上若只测首包延迟而不测这条链上的中间量，就无法判断延迟收益来自命中率还是来自并发被压低。</p>\n<div class=\"formula\">$$\\lambda_{\\text{spec}}=\\frac{N_{\\text{concurrent}}\\cdot \\mathbb{E}[\\text{triggers per session}]}{\\mathbb{E}[\\Delta\\tau]},\\quad W_{\\text{redundant}}=\\lambda_{\\text{spec}}\\cdot K\\cdot c_{\\text{decode}}$$</div>\n<p>其中 <code>λ_spec</code> 是推测触发速率，<code>W_redundant</code> 是单位时间冗余解码算力，<code>c_decode</code> 是单 token 解码代价。这个式子给出一个直接判断：在并发会话数上升时，若 <code>λ_spec</code> 不受控，冗余算力会线性膨胀，而首包延迟的改善却是每个会话各自的、不随并发叠加的——这就是负载塑造方案的第一条约束。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-9\">九 · SLO 的分解：首包延迟是唯一硬指标，其余是软约束</h3>\n<p>实时语音交互的 SLO 必须写成可判定的分位数形式，而不是“平均响应时间”。核心硬指标是<strong>首包延迟</strong>：从最终输入确定（识别流给出终止信号）到第一个合成音频包可播放的时间，记为 <code>L_first</code>，考核口径是 P50 与 P99 两条线，因为长尾会话才是用户感知到的卡顿。软约束包括端到端响应时间、单位请求冗余算力上限、以及回退重算频率。PredGen 的结构决定了 <code>L_first</code> 可以被拆成三段可分别测量的量：</p>\n<div class=\"formula\">$$L_{\\text{first}}=L_{\\text{finalize}}+L_{\\text{verify}}+L_{\\text{resume}}(k)$$</div>\n<p><code>L_finalize</code> 是识别流终止与最终前缀确定的耗时，<code>L_verify</code> 是最长公共前缀比对与 KV 命中判定的耗时，<code>L_resume(k)</code> 是从第 k 个命中 token 之后继续解码到首包可发声的步数代价。推测的收益全部体现在 <code>L_resume(k)</code> 上：k 越大，剩余解码步数越少。注意 <code>L_verify</code> 不是零成本——它要逐 token 比对，且必须在 KV 缓存管理里定位可复用的块边界，因此校验本身是一个与命中长度成正比的串行段。把 <code>L_first</code> 拆成这三段，才能回答“推测到底省了哪一段”，而不是笼统地说延迟下降。</p>\n<p>具体例子：一个会话在识别流给出终止信号时前缀长度为 <code>n</code>，推测阶段已生成 K 个候选 token，校验发现前 k 个一致。若不做推测，首包需要从 <code>n</code> 之后解码若干步；做推测后只需从 <code>n+k</code> 之后解码。省下的步数是 k，但代价是推测阶段消耗了 K 次解码前向，且这 K 次前向发生在用户还在说话的窗口内——它挤占的是同一张卡上其他会话的算力。因此 SLO 里必须同时写“首包延迟 P99 上限”和“冗余算力占比上限”，二者构成一对互相拉扯的约束，缺一个就无法做容量规划。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-10\">十 · 长尾从哪里来：识别纠错、触发抖动与批内错配</h3>\n<p>PredGen 的延迟长尾有三个可归因的来源，每一个都能用独立口径测量。第一是<strong>识别纠错破坏前缀一致性</strong>：流式识别在后续增量中修正先前词，导致最终前缀与推测前缀在早期位置就分歧，命中长度 k 退化为 0 或极小值。测量口径是“分歧位置分布”，即 k 的直方图，而不是平均命中率——平均值会把“大部分会话命中很长、少数会话完全失效”这个双峰结构抹平，而 P99 恰恰由后者决定。第二是<strong>触发抖动</strong>：推测触发器在检测到停顿或增量时启动，若 <code>Δτ</code> 不稳定，触发点可能落在前缀极短的时刻，此时推测的上下文不足，命中率天然偏低。测量口径是“触发时前缀长度”与“该次推测命中长度”的联合分布。第三是<strong>批内错配</strong>：增量预填把不同会话的新增 token 拼进同一批，序列长度差异大时，短序列被 padding 拖慢，长序列被批大小限制拖慢，二者叠加使批的实际有效吞吐低于名义吞吐。测量口径是批内长度向量的变异系数与 padding 占比。</p>\n<p>这三条长尾对方案的反馈是明确的：纠错型长尾要求校验器在分歧时快速丢弃并回退，回退路径的代价必须与正常路径同量级，否则一次失效就吃掉多次命中的收益；触发抖动型长尾要求触发器带最小前缀长度门限，宁可少推测也不要在上下文不足时浪费 K 次前向；批内错配型长尾要求增量预填按新增 token 数分桶，而不是按会话到达顺序拼批。这三条都不是模型层面的改动，而是调度与缓存管理层面的工程判断。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-11\">十一 · 负载反过来限制方案：K 的上界由并发与显存共同钉死</h3>\n<p>推测长度 K 看似是自由超参，实际上被负载钉死。每个会话在推测阶段持有 K 个候选 token 的 KV，加上已确认前缀的 KV，单会话 KV 占用随 K 线性增长。并发会话数为 <code>N</code> 时，推测阶段的 KV 峰值约为 <code>N·(KV_prefix + K·kv_per_token)</code>。在 Blackwell 的显存档位下，这个峰值直接决定 <code>N</code> 的上界，而 <code>N</code> 又决定摊薄后的单位请求成本。因此 K 的选择不是“命中率越高越好”，而是在给定显存预算下最大化 <code>k/K</code> 的期望收益：</p>\n<div class=\"formula\">$$\\text{gain}(K)=\\mathbb{E}[k\\mid K]\\cdot c_{\\text{decode}}-\\bigl(1-\\mathbb{E}[k\\mid K]/K\\bigr)\\cdot K\\cdot c_{\\text{decode}}-\\Delta_{\\text{kv}}(K)$$</div>\n<p>第一项是命中节省的解码代价，第二项是未命中部分被丢弃的浪费，第三项是 KV 占用上升带来的并发下降代价。三项里只有第一项随 K 单调上升，后两项都随 K 上升，所以存在一个由负载决定的内部最优点。工程上可核查的做法是：固定并发档位与显存预算，扫 K 的几个取值，记录 <code>L_first</code> 的 P50/P99 与冗余算力占比，取 P99 满足 SLO 前提下的最小 K。这个扫描必须在目标硬件与目标量化方案下做，因为 NVFP4/FP8 下 KV 的字节占用与数值一致性都会改变上述三项的相对大小。</p>\n<p>负载对方案的第二条限制是<strong>推测触发不能无限频繁</strong>。若每个增量都触发一次推测，<code>λ_spec</code> 随 <code>Δτ</code> 变小而暴涨，冗余算力挤占正常解码，反而拉高 P99。可行的约束是给触发器设一个最小间隔与最小新增 token 数门限，使 <code>λ_spec</code> 与并发数解耦。这条约束的代价是部分本可命中的推测窗口被放弃，收益上限下降，但它把长尾从“算力争抢”变成“可控的少推测”，在 SLO 考核上更稳。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-12\">十二 · 可核查的测量口径清单</h3>\n<p>为了让不同部署之间的数据可比，测量口径必须固定到字段级。下表给出本方案落地时应记录的最小集合，每一行都对应一个可独立采集的量，而不是派生指标。</p>\n<table class=\"mini\"><thead><tr><th>口径</th><th>定义</th><th>用途</th></tr></thead><tbody>\n<tr><td>前缀长度分位</td><td>终止时刻 <code>len(prefix)</code> 的 P50/P90/P99</td><td>判断负载是否偏长、推测窗口是否充足</td></tr>\n<tr><td>增量节奏</td><td><code>Δn/Δτ</code> 的分布与 <code>Δτ</code> 的抖动</td><td>决定触发门限与增量预填分桶</td></tr>\n<tr><td>命中长度直方图</td><td>校验后 k 的分布，含 k=0 的比例</td><td>识别纠错型长尾，评估回退频率</td></tr>\n<tr><td>首包延迟三段</td><td><code>L_finalize</code>、<code>L_verify</code>、<code>L_resume</code> 各自分位</td><td>定位收益来自哪一段，避免笼统归因</td></tr>\n<tr><td>冗余算力占比</td><td>推测前向 token 数 / 总解码 token 数</td><td>与并发、K 联合做容量规划</td></tr>\n<tr><td>批内 padding 占比</td><td>padding token 数 / 批总 token 数</td><td>衡量增量预填的批效率损失</td></tr>\n<tr><td>KV 峰值</td><td>推测阶段单会话与全局 KV 占用峰值</td><td>钉死并发上界与 K 的上界</td></tr>\n</tbody></table>\n<p>这张表的关键在于“三段拆分”与“直方图而非均值”两条。前者防止把校验成本误记为推测收益，后者防止用平均命中率掩盖双峰长尾。任何声称加速比的数据，若不附带 k 的直方图与冗余算力占比，就无法判断它是否在低并发、高命中率的理想条件下取得，也就无法外推到生产负载。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-13\">十三 · 方案对负载的反向塑造：从“来什么算什么”到“按窗口排布”</h3>\n<p>PredGen 一旦上线，它不只被动接受负载，还会反向塑造负载形态。最直接的一条是<strong>推测窗口把请求的到达时间重新分组</strong>：原本按会话到达顺序排队的请求，被推测触发点切成“说话中”与“已终止”两类，前者占用推测算力，后者占用解码算力。调度器若按这两类分别排队，就能让推测批次与解码批次各自保持较均匀的序列长度，降低批内错配。代价是需要维护两条队列与它们之间的优先级规则，且终止事件会触发跨队列迁移，迁移本身有缓存失效成本。</p>\n<p>第二条反向塑造是<strong>K 的自适应收缩</strong>。当并发上升、KV 峰值逼近显存预算时，系统主动把 K 调小，把算力让给已终止会话的解码；当并发下降时再放大 K。这个策略把 K 从静态超参变成负载的函数，其收益是 P99 更稳，代价是命中率随负载波动，单次推测的收益不再可预测。工程判断上，是否值得做自适应，取决于负载的并发方差：方差大则自适应收益明显，方差小则固定 K 加保守门限更简单、更可审计。</p>\n<p>第三条是<strong>校验与 KV 复用的粒度反过来决定前缀切分</strong>。若 KV 缓存按固定块管理，命中长度 k 必须对齐到块边界才能整块复用，未对齐部分要么重算要么保留碎片。这迫使输入缓冲在切分前缀时考虑块对齐，而不是纯粹按语音到达节奏切。结果是负载的切分粒度被方案的缓存结构反向约束——这是一个典型的“方案限制负载”的例子，也是部署时必须显式记录的耦合点：块大小、对齐策略与切分节奏三者共同决定实际可复用的 KV 比例，而这个比例直接进入 <code>L_resume</code> 的分子。</p>\n<p>最后落到一个具体机制上：一致性校验器的比对顺序应当从最早 token 开始逐位推进，一旦分歧立即截断，而不是先算完整公共前缀再判定。原因是分歧位置在纠错型负载下偏向早期，逐位早停能把 <code>L_verify</code> 的期望代价压到与命中长度成正比的下界附近；若反过来做，校验成本会退化为与前缀总长成正比，在长会话上吃掉推测收益。这个判断不依赖任何未给出的实验数字，只依赖“分歧偏向早期”这一负载事实与“比对可早停”这一机制事实。</p>\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-14\">十四 · 推测路径上的核心算子与数据流</h3>\n<p>PredGen 的推测发生在输入阶段，其算子序列与常规自回归解码并无二致：增量预填的 GEMM、逐 token 的解码 GEMM、注意力打分与 softmax、MLP 与归一化。差别在于调用节奏——一次推测触发会在极短时间内连续执行 K 步解码，K 是固定超参，随后整段路径被校验器裁决为接受或丢弃。这意味着核心 kernel 的形态是“小 batch、短序列、高频次”：预填阶段的矩阵乘规模由新增 token 数决定，通常只有个位数到数十个 token；解码阶段则是 batch 为 1 或并发会话数、序列长度为 1 的瘦长 GEMM。在 Blackwell 上，这类形状的算术强度极低，性能瓶颈落在权重读取带宽与 kernel 启动开销上，而非 Tensor Core 的浮点峰值。因此推测路径的 kernel 选择必须优先考虑“小 M 维度下的有效利用率”，而不是峰值 FLOPS 数字。</p>\n<p>把一次推测的代价写成可分解的形式：</p>\n<div class=\"formula\">$$C_{\\text{spec}} = \\underbrace{K \\cdot \\big(c_{\\text{attn}} + c_{\\text{mlp}}\\big)}_{\\text{解码步}} + \\underbrace{c_{\\text{prefill}}(n_{\\text{new}})}_{\\text{增量预填}} + \\underbrace{c_{\\text{verify}}(k)}_{\\text{前缀比对}}$$</div>\n<p>其中 c_attn 与 c_mlp 是单步解码中注意力与 MLP 的耗时，主要由权重带宽决定；c_prefill 随新增 token 数 n_new 线性增长；c_verify 只做前缀比对，量级远小于前两项。命中时这整笔代价被摊薄到被复用的 k 个 token 上，等效解码步数下降，与 L_eff 的定义一致；未命中时 c_spec 全额沉没，还要追加从分歧点重算的预填。工程判断因此很直接：推测长度 K 必须与命中率 h 联合标定，单看 K 没有意义。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-15\">十五 · 数据类型选择：FP16/BF16、FP8 与 NVFP4</h3>\n<p>推测解码沿用原模型权重，数据类型首先由主模型决定。BF16 与 FP16 在 Blackwell 上都有原生支持，BF16 的动态范围更宽，适合激活值分布跨度大的层；FP16 尾数多一位，在需要精细数值的归一化与 softmax 路径上更稳。两者在推测路径上的实际差异不在算力，而在校验一致性：同一前缀在两次前向中必须给出可复现的 logits 排序，否则温度采样下的随机数状态无法对齐，复用 token 会偏离原分布。这是无损加速的前提，任何降低精度的改动都要先过这一关。</p>\n<p>FP8 把权重与激活压到 8 位，权重读取字节数减半，直接缓解小 batch 解码的带宽瓶颈。代价是量化误差进入 logits，前缀比对虽然只比 token id，但 token id 由 logits 的 argmax 或采样决定，误差足以在接近的候选之间翻转选择，从而把一次本应命中的推测变成分歧。NVFP4 进一步压到 4 位，配合分块缩放因子维持动态范围，权重带宽再降，但误差量级更大，对校验稳定性的威胁也更直接。对 PredGen 这类以“前缀完全一致”为复用条件的机制，量化不是免费的吞吐提升，而是把命中率 h 变成一个随精度下降的函数。部署时的正确做法是把量化误差纳入命中率实测，而不是先量化再假设 h 不变。</p>\n<table class=\"mini\"><thead><tr><th>数据类型</th><th>权重带宽压力</th><th>对校验一致性的影响</th><th>适用位置</th></tr></thead><tbody><tr><td>BF16</td><td>基准</td><td>可复现性最好</td><td>主模型默认，校验基准</td></tr><tr><td>FP16</td><td>与 BF16 相当</td><td>尾数精度略优，范围较窄</td><td>注意力与归一化敏感层</td></tr><tr><td>FP8</td><td>约减半</td><td>logits 抖动，接近候选易翻转</td><td>大权重 GEMM，需实测 h</td></tr><tr><td>NVFP4</td><td>显著下降</td><td>误差最大，校验失败率上升</td><td>带宽受限的解码路径，谨慎启用</td></tr></tbody></table>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-16\">十六 · 累加精度与误差传播</h3>\n<p>低精度乘法的误差并不只来自操作数位宽，累加器的位宽同样决定结果。Tensor Core 在 FP8 与 NVFP4 路径上以更高精度累加，通常是 FP32 或分块缩放后的定点累加，目的是让长归约的和不被中间舍入吞掉。对推测路径而言，关键归约有两处：注意力打分对键维度的求和，以及 MLP 中对隐藏维度的求和。前者决定 softmax 前的相对排序，后者决定激活幅值。若累加精度不足，即便权重是 BF16，长序列下的打分也会漂移，进而改变被选中的 token。</p>\n<p>误差传播可以用一个简单的界来刻画：设单次乘加的相对误差为 ε，归约长度为 n，则最坏情况下和的相对误差约为 n·ε，实际因随机抵消通常低于此界。写成：</p>\n<div class=\"formula\">$$\\big|\\hat{s}-s\\big| \\lesssim n\\,\\varepsilon\\,\\|x\\|\\,\\|w\\|,\\qquad \\varepsilon \\propto 2^{-b}$$</div>\n<p>其中 b 是有效尾数位宽，x 与 w 是参与归约的激活与权重。这个式子解释了为什么 FP8 在短序列上表现尚可、在长上下文注意力里误差累积更明显：n 随上下文增长。对 PredGen，推测发生在前缀尚短的阶段，n 较小，误差界相对宽松，这是低精度在输入阶段比在长上下文解码阶段更可用的结构性原因。但增量预填会把前缀逐步拉长，误差随会话推进而增长，校验失败率也随之上升，需要在 KV 复用策略里留出回退余量。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-17\">十七 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA</h3>\n<p>Blackwell 的第五代 Tensor Core 通过 tcgen05 指令族暴露给 kernel 作者，其核心变化是把矩阵乘的累加器从寄存器文件搬到 Tensor Memory（TMEM）。TMEM 是每 SM 专用的片上存储，专门承载 MMA 的累加结果，使大块 MMA 不必把中间结果反复写回寄存器堆再溢出到共享内存。对推测路径的意义在于：解码阶段的瘦长 GEMM 虽然算术强度低，但累加器驻留 TMEM 减少了寄存器压力与数据搬运，让 kernel 在 batch 很小时仍能维持较高的发射密度。代价是 TMEM 容量有限，多个并发会话的 KV 与中间结果争用同一片 TMEM 时，occupancy 会被压缩，吞吐随并发数非线性下降。</p>\n<p>2-SM MMA 是另一项关键特性：一对 SM 协同执行一次更大的 MMA，把权重分片到两个 SM 上并行读取与计算。对权重带宽受限的解码 GEMM，这相当于把单次权重读取的有效带宽翻倍，直接攻击前述瓶颈。伪代码层面的调度思路是：</p>\n<div class=\"formula\">$$\\text{for each } t:\\ \\ \\text{MMA}_{2\\text{SM}}\\big(W[:, t],\\ h_{t-1}\\big)\\ \\rightarrow\\ \\text{TMEM};\\ \\ \\text{softmax};\\ \\ \\text{sample}(t)$$</div>\n<p>即每个解码步把权重切片沿 2-SM 对分发，累加结果落 TMEM，随后做注意力与采样。这里的工程代价是同步：2-SM MMA 要求两个 SM 的进度对齐，任一 SM 被其他会话的 kernel 抢占都会拖慢整对，因此推测触发应尽量与批内其他请求的解码错峰，避免在 2-SM 对上制造争用。功耗层面，TMEM 驻留减少了寄存器与共享内存的翻转活动，单位 token 的能量下降，但高频次的小 kernel 启动会带来固定的调度开销，推测长度过短时这部分开销占比上升。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-18\">十八 · 校验环节的数值一致性要求</h3>\n<p>校验器做的是最长公共前缀比对，看似与数值精度无关，实则强耦合。命中条件是推测 token 序列与最终前缀逐位相同，而 token 由 logits 经采样或 argmax 产生。温度采样下，采样结果依赖随机数状态；若推测与正式解码使用了不同的 kernel 实现或不同的累加路径，同一前缀的 logits 会有微小差异，随机数状态一旦错位，复用 token 就偏离原模型分布，无损性被破坏。工程上的做法是把推测与正式解码绑定到同一套 kernel 与同一精度配置，并在会话维度维护随机数种子与计数器，使第 k 步的采样状态可精确复现。</p>\n<p>另一个隐性代价是 KV 缓存的精度。命中复用的 KV 由推测阶段以低精度写入，正式解码继续使用时，其数值与“从未推测、直接解码”的路径不完全相同。对短前缀影响可忽略，但前缀增长后误差累积会改变后续注意力分布。因此在 FP8/NVFP4 部署下，KV 缓存通常保留更高精度（如 BF16 存储、低精度计算），用显存换一致性。这直接抬高并发会话的显存占用，与批调度策略耦合：并发越高，KV 越大，TMEM 与显存争用越紧，推测的净收益越依赖命中率而非单纯的长度堆叠。</p>\n<p>落到工程判断上：PredGen 在 Blackwell 上的加速上限不由 Tensor Core 峰值决定，而由“小 batch 解码的权重带宽 + 校验一致性”这一对约束共同决定。把推测长度 K、量化档位与 KV 精度作为一个联合配置来标定，用实测命中率与首包延迟分位数做闭环，才是这套机制在 SM100/SM103 上可复用的落地方式。</p>\n\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-19\">十九 · 推测命中的数值边界：FP8/NVFP4 下校验为何先于算力失效</h3>\n<p>PredGen 的校验不是字符串比较，而是“同一前缀、同一随机数状态、同一数值路径下前向结果是否逐 token 等价”。在 BF16 下，原模型对前缀的确定性前向基本可复现，最长公共前缀比对可靠；一旦把增量预填与推测解码切到 FP8 或 NVFP4，tcgen05 的 2-SM MMA 走 TMEM 累加，累加器位宽与缩放因子（scale）选择直接决定 logits 的微小偏移。若推测段用 NVFP4 块缩放、校验段用 FP8 per-tensor 缩放，同一 token 的 argmax 可能在分歧点附近翻转，校验器会把本可复用的 k 个 token 判为失效。工程上的硬约束是：推测与校验必须共享同一量化配置与同一 kernel 变体，否则命中率被数值噪声吃掉，公式里的 h 被系统性低估。<div class=\"formula\">$$L_{\\text{eff}}=\\frac{T_{\\text{decode}}}{1+\\alpha\\cdot h},\\quad h=\\frac{|P_{\\text{spec}}\\cap P_{\\text{final}}|}{|P_{\\text{spec}}|}$$</div>逐项看：T_decode 是串行解码步数对应的墙钟时间，α 是单次推测相对单步解码的算力放大系数，h 是命中率。关键在分母 1+α·h——当 h 因量化不一致从接近 1 跌到中段，α 越大反噬越重；而 NVFP4 下 α 并不因位宽降低而线性缩小，因为反量化、scale 广播与 TMEM 读写仍占时间。</p>\n<p>Blackwell 的第五代 Tensor Core 把 MMA 从寄存器堆搬到 TMEM，2-SM MMA 让一对 SM 共享一次大 MMA 的累加器，单次发射的 K 维更大、累加精度更高，但代价是 TMEM 容量成为并发推测的硬上限。每个会话的推测 KV 与中间激活都要在 TMEM/SMEM 间周转，并发会话数一多，TMEM 分配冲突会让 kernel 退化为串行发射，推测的“提前算”变成“排队算”。此时即便 h 很高，L_eff 也降不下来，因为 T_decode 被资源争用拉长。具体例子：GB200 NVL72 单机架内多路语音会话同时触发推测，若每路固定推测长度 K 且都用 2-SM MMA 变体，TMEM 占用随并发线性上升，调度器被迫降低每路 K 或错峰触发，命中收益被摊薄。</p>\n<p>失效条件集中在三处。其一，流式识别纠错：用户中途改口或 ASR 回改前词，最终前缀与推测前缀在早期分叉，k 接近零，整段推测 KV 作废，增量预填还要为新前缀重算，净代价是负的。其二，温度采样：复用推测 token 需保持随机数状态一致，若校验后从分歧点重采样而 RNG 流已偏移，输出分布偏离原模型，“无损”前提破裂。其三，低命中率下的长推测：K 增大使 α 与 KV 显存同步上升，回退重算的预填量按分歧点后的 token 数计，显存碎片与回退频率一起抬高。可操作的判断是给 K 设上限并按增量到达节奏自适应收缩，同时把校验做成前缀比对而非全量重前向，把回退成本压到新增 token 的增量预填量级。<table class=\"mini\"><thead><tr><th>配置</th><th>校验可靠性</th><th>主要系统代价</th></tr></thead><tbody><tr><td>BF16 推测+校验</td><td>高，argmax 稳定</td><td>显存与带宽占用最高</td></tr><tr><td>FP8 同配置</td><td>中高，需固定 scale</td><td>反量化开销、TMEM 周转</td></tr><tr><td>NVFP4 推测/FP8 校验</td><td>低，易误判分歧</td><td>命中率下降、回退重算增多</td></tr></tbody></table>这张表的工程含义是：量化档位不是独立调优项，它和校验策略、K 的取值绑定；在材料未给出硬件档位与量化方案的前提下，任何加速比外推都不可信，落地必须先测同配置下的 h 与 α，再决定是否启用 NVFP4 推测段。</p>\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-20\">二十 · 显存账本的三条腿：权重、激活、KV</h3>\n<p>在 Blackwell 上给 PredGen 做显存预算，第一步是把账本拆成三块互不重叠的占用：静态权重、前向瞬时激活、以及随会话增长的 KV cache。三者性质不同——权重是常量，激活是每步前向的峰值，KV 是随并发与序列长度单调累积的状态。PredGen 的特殊之处在于它同时把 KV 的“时间轴”拉长了：推测阶段生成的候选 token 也持有 KV，这部分 KV 在最终前缀确定前处于“待定”状态，命中则转为正式缓存，未命中则整段作废。因此预算不能只按“最终序列长度 × 并发”算，必须为推测分支预留一份可回收的暂存区。</p>\n<p>设模型层数 $L$、KV 头数 $H_{kv}$、头维度 $d$、每元素字节数 $b$，则单 token 的 KV 字节数为：</p>\n<div class=\"formula\">$$S_{\\text{kv}}=2\\cdot L\\cdot H_{kv}\\cdot d\\cdot b$$</div>\n<p>系数 2 来自 K 与 V 两份。以 GQA 的典型配置为例，$L=80$、$H_{kv}=8$、$d=128$、FP8 下 $b=1$，则单 token 约 164 KB；若换 NVFP4 存储 KV，$b$ 降到 0.5，单 token 约 82 KB，但要注意 KV 的量化误差会直接进入校验环节——推测 token 与重算 token 若走不同精度路径，最长公共前缀比对就不再是纯文本比对，而要先确认数值一致性。这是 PredGen 在低精度部署下必须显式处理的一条约束，不能默认无损。</p>\n<p>激活占用则是另一回事：它不随序列长度线性增长，而随批大小与推测长度 K 的乘积增长。推测解码一次前向要同时处理 K 个候选位置，激活峰值近似正比于 $(B\\cdot K)$，其中 B 是并发批。K 越大，单次前向的临时显存越高，且这部分内存在校验完成前不能释放。工程上常见的做法是把推测分支的激活与 KV 暂存划入独立的显存池，用固定上限约束 K，避免长推测把主池挤爆。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-21\">二十一 · 分页与碎片：为什么推测分支最怕外部碎片</h3>\n<p>KV cache 的分页（paged attention 一类机制）把逻辑序列切成固定大小的块，块表映射到物理页。它的核心收益是消除“按最大长度预留”造成的内部碎片，让并发会话按实际增长占用显存。但对 PredGen 而言，分页带来一个新的问题：推测分支的 KV 是一段“可能被整体丢弃”的连续逻辑区间，若它与已确认前缀共享物理页，回退时无法只释放后半段而不动前半段。因此合理的布局是让推测区间从独立的页开始，校验通过后再把页并入主序列的块表；未通过则整段归还空闲页链表。</p>\n<p>碎片代价可以定性估算：若页大小为 $P$ 个 token，每个推测分支平均浪费半页，则并发 $N$ 路推测的碎片上限约为 $N\\cdot P/2$ 个 token 的 KV 空间。当 $N$ 较大、$P$ 取 16 或 32 时，这部分不可忽视。更隐蔽的是回退重算导致的页反复分配与释放——高回退率下分配器抖动会推高尾延迟，这与吞吐无关，却直接打在首包延迟的 P99 上。PredGen 的收益恰恰体现在首包延迟，所以碎片治理不是可选项。</p>\n<p>一个具体例子：某会话前缀已确认 512 token，推测 K=64，命中前 40 个。若推测区间独立成页，则只需把前 40 个 token 所在的页并入主链，剩余 24 个 token 的页直接回收；若混排在同一页内，则要么整页保留（浪费 24 个 token 的空间直到序列结束），要么触发一次页内搬迁，搬迁本身要拷贝 KV，带宽开销与页大小成正比。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-22\">二十二 · 压缩与复用：命中即复用，复用即省带宽</h3>\n<p>PredGen 的 KV 复用是它最直接的显存与带宽收益来源。校验命中 k 个 token，意味着这 k 步解码的 KV 读写被整体跳过——不只是省了算力，更省了把这 k 个 token 的 KV 重新写回 HBM 的带宽。自回归解码每步都要把新 token 的 K、V 写入缓存，并在后续每步把全部历史 KV 读一遍（在无跨步复用的朴素实现里）。因此复用 k 个 token 等价于砍掉 k 次写与若干次读。</p>\n<p>解码阶段的带宽账可以写成：单步解码需读取的 KV 字节数约为 $S_{\\text{kv}}\\cdot n_{\\text{ctx}}$，其中 $n_{\\text{ctx}}$ 是当前上下文长度。在 batch=1、上下文数千 token 的场景下，这一步的 HBM 读取量远超权重读取量，解码因此是带宽瓶颈而非算力瓶颈。PredGen 把一部分这样的读取提前到输入阶段完成，等于把带宽需求在时间上摊平——用户说话的那几秒里 GPU 本来在空转等输入，此时用闲置带宽做推测前向，边际成本很低。这正是它“用冗余算力换延迟”在显存带宽层面的解释。</p>\n<p>压缩方面，KV 的低精度存储（FP8/NVFP4）能把 $S_{\\text{kv}}$ 减半乃至更多，代价是校验的数值稳定性。工程判断是：推测分支与正式缓存应使用同一精度路径，否则命中判定要额外做数值容差比较，反而增加校验开销。若必须混用，应把容差比较放在 CPU 侧或单独的轻量核里，避免占用解码主路径的 SM。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-23\">二十三 · 卸载：把冷 KV 挪出 HBM 的边界条件</h3>\n<p>HBM3e 容量决定了能同时驻留多少会话的 KV。以单卡 141 GB 级别（B200 档位）为例，扣掉权重与激活后，可用于 KV 的空间是有限的；GB200 NVL72 机架把 72 个 GPU 连成域，容量总量上去了，但单卡仍需面对“本卡 KV 装不下全部活跃会话”的问题。卸载（offload）到主机内存或远端池是常见手段，但对 PredGen 有一个硬约束：推测分支的 KV 在输入阶段被写入后，可能在几百毫秒内就要被校验读取，这个时间窗远短于典型的冷数据卸载周期。把推测 KV 卸载出去，等于在校验时引入一次 PCIe 往返，直接吃掉它换来的延迟收益。</p>\n<p>因此卸载策略应分层：已确认的长前缀中、近期不会被注意到的远端 token 可以下沉；推测分支的 KV 必须留在 HBM 或至少留在 L2 可及的范围。判断依据是“下次被读的时间距离”——推测 KV 的复用距离极短，属于最热的数据。这条规则同样适用于分离式预填/解码架构：预填节点产出的 KV 若要传给解码节点，传输带宽（NVLink 5 或 NIXL 路径）就是新的瓶颈，推测 KV 的传输优先级应高于历史 KV。</p>\n<p>代价上，一次主机内存往返的延迟在微秒到数十微秒量级，看似不大，但推测校验是串在首包关键路径上的，任何一次额外往返都会累加到用户可感知的空档里。卸载的收益是容量，代价是关键路径延迟，二者在 PredGen 里是直接对立的。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-24\">二十四 · 可复算的显存预算</h3>\n<p>下面给出一份可自行代入参数的预算表。假设单卡 HBM 容量 $C$，权重占用 $W$（由参数量与精度决定），激活峰值 $A$（由批大小与 K 决定），则可用于 KV 的容量为 $C-W-A$。可支撑的并发会话数上界为：</p>\n<div class=\"formula\">$$N_{\\max}=\\left\\lfloor\\frac{C-W-A}{S_{\\text{kv}}\\cdot(\\bar{n}_{\\text{ctx}}+K_{\\text{spec}})}\\right\\rfloor$$</div>\n<p>分母里 $\\bar{n}_{\\text{ctx}}$ 是平均上下文长度，$K_{\\text{spec}}$ 是每路预留的推测暂存 token 数。注意这里把推测暂存按“最坏情况全部保留”计入，实际可乘以一个回收系数（命中率越高，暂存的实际驻留时间越短，但容量上界仍按峰值算）。</p>\n<table class=\"mini\"><thead><tr><th>项目</th><th>决定因素</th><th>随什么增长</th><th>可否压缩</th></tr></thead><tbody>\n<tr><td>权重 W</td><td>参数量 × 精度字节</td><td>常量</td><td>NVFP4/FP8 量化</td></tr>\n<tr><td>激活 A</td><td>批大小 × 推测长度 K</td><td>B·K</td><td>限制 K、分池</td></tr>\n<tr><td>正式 KV</td><td>$S_{\\text{kv}}\\cdot n_{\\text{ctx}}$</td><td>并发 × 上下文</td><td>低精度、分页</td></tr>\n<tr><td>推测暂存 KV</td><td>$S_{\\text{kv}}\\cdot K$</td><td>并发 × K</td><td>独立页、及时回收</td></tr>\n</tbody></table>\n<p>代入一组可复算的数：设 $C=141$ GB，$W$ 取 70 GB（大模型 FP8 量级），$A$ 取 8 GB，则 KV 池约 63 GB。若 $S_{\\text{kv}}=164$ KB/token，$\\bar{n}_{\\text{ctx}}=2048$，$K_{\\text{spec}}=64$，则每路占用约 $(2048+64)\\times164\\text{ KB}\\approx346$ MB，$N_{\\max}\\approx182$ 路。若 KV 改 NVFP4、$S_{\\text{kv}}$ 减半，则并发翻倍——这就是精度选择对容量的杠杆。反过来，若把 K 从 64 提到 256，每路多占约 31 MB，$N_{\\max}$ 下降约 9%，且激活峰值同步上升，双重挤压。</p>\n<p>这张表的价值在于它把 PredGen 的超参 K 直接映射到了容量与并发上：K 不是纯粹的延迟旋钮，它同时是显存旋钮。调 K 时必须同步重算 $N_{\\max}$，否则会在高并发下触发 KV 分配失败或被迫卸载，把延迟收益抵消掉。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-25\">二十五 · 带宽瓶颈落在哪：一次解码步的读写剖面</h3>\n<p>把一次解码步的 HBM 流量拆开看，权重读取量约为 $W_{\\text{active}}$（当前层或全部层，取决于是否分层驻留），KV 读取量约为 $S_{\\text{kv}}\\cdot n_{\\text{ctx}}$，KV 写入量约为 $S_{\\text{kv}}$。在小批、长上下文下，KV 读占主导；在大批下，权重读被摊薄，KV 读随批线性上升但仍按 token 计。PredGen 改变的是这个剖面的时间分布：推测阶段提前完成了一部分 KV 写与后续读，校验命中后这些流量不再发生。</p>\n<p>量化收益的定性表达是：命中 k 个 token，节省的 KV 流量约为 $k\\cdot S_{\\text{kv}}\\cdot(1+n_{\\text{ctx}}/2)$ 量级（写一次、后续平均读若干次），而付出的代价是推测阶段对 K 个位置做了一次前向的激活与 KV 写。当命中率 $h$ 高、$k$ 接近 K 时，净流量为负（省多于花）；当 $h$ 低时，推测的 KV 写全部作废，净流量为正，且回退重算还要再写一遍。这与公式 $L_{\\text{eff}}=T_{\\text{decode}}/(1+\\alpha h)$ 的方向一致：带宽账和延迟账由同一个命中率驱动。</p>\n<p>工程判断落在最后这一点上：在 Blackwell 上部署 PredGen，显存预算的第一约束不是总容量，而是推测暂存区的峰值与回收节奏；带宽预算的第一约束不是峰值带宽，而是推测 KV 的复用距离是否短到值得留在 HBM。把 K 当作延迟与显存的双向旋钮、把推测 KV 当作最热数据而非可卸载冷数据，是这套机制在容量受限档位上不塌的前提。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-26\">二十六 · 推测窗口的显存账本与失效边界</h3>\n<p>PredGen 的显存开销不在权重，而在“推测前缀 × 并发会话”的 KV 冗余。设单会话最终前缀长度为 <span class=\"inline-math\">S</span>、单次推测长度为 <span class=\"inline-math\">K</span>、层数 <span class=\"inline-math\">L</span>、KV 头数 <span class=\"inline-math\">H</span>、头维 <span class=\"inline-math\">d</span>、每元素字节 <span class=\"inline-math\">b</span>，则一次推测额外驻留的 KV 为 <span class=\"inline-math\">\\(M_{\\text{spec}}=2\\cdot L\\cdot H\\cdot d\\cdot K\\cdot b\\)</span>，命中后仅保留公共前缀 <span class=\"inline-math\">k</span> 对应的部分，其余 <span class=\"inline-math\">K-k</span> 个 token 的 KV 必须立即释放。真正决定容量的不是 <span class=\"inline-math\">S</span> 而是 <span class=\"inline-math\">S+K</span> 的峰值，因为推测 KV 与已确认前缀 KV 在窗口内共存；分页分配器必须把这段推测区当作可回收页管理，否则回退时留下的空洞会推高碎片率。</p>\n<div class=\"formula\">$$M_{\\text{peak}}=N_{\\text{conc}}\\cdot 2LHb\\big[(S+K)d\\big],\\qquad \\eta=\\frac{k}{K}$$</div>\n<p>净收益的判据可以写成解码步数节省与冗余算力之比：有效解码长度按 <span class=\"inline-math\">\\(L_{\\text{eff}}=T_{\\text{decode}}/(1+\\alpha h)\\)</span> 缩短，但只有 <span class=\"inline-math\">h</span> 接近 1 时，<span class=\"inline-math\">K</span> 增大才线性兑现为首包延迟下降；当 <span class=\"inline-math\">h</span> 低于约 <span class=\"inline-math\">1/K</span> 量级，回退重算的预填与解码开销会吃掉全部收益。带宽侧同理：增量预填的代价与新增 token 数成正比而非总前缀长度，因此每步 HBM3e 流量由 <span class=\"inline-math\">\\(\\Delta S\\)</span> 决定，但推测 KV 的写回与丢弃是纯带宽浪费，在低命中率下这部分写入会与正常解码争抢 HBM 带宽，把首包延迟的瓶颈从算力搬到显存子系统。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>机制后果</th><th>系统代价</th></tr></thead><tbody><tr><td>流式识别纠错改写前缀</td><td>公共前缀长度 k 骤降，推测整体作废</td><td>回退重算 + KV 释放/重分配，首包延迟反超基线</td></tr><tr><td>K 过大且 h 偏低</td><td>推测 KV 峰值占用翻倍</td><td>并发会话数被迫下调，吞吐下降</td></tr><tr><td>温度采样随机状态不一致</td><td>复用 token 偏离原分布</td><td>校验通过但输出不可复现，无损性失效</td></tr></tbody></table>\n<p>一个可复算的例子：若 <span class=\"inline-math\">K=8</span>、命中 <span class=\"inline-math\">k=6</span>，则 <span class=\"inline-math\">\\(\\eta=0.75\\)</span>，仅 2 个 token 的 KV 被丢弃，增量预填只需处理识别流新增的少量 token；反之若首个 token 即分歧，<span class=\"inline-math\">\\(\\eta=0\\)</span>，这 8 个 token 的 KV 写入全部作废，等于用一次完整短程解码的带宽换零收益。工程判断是：推测区必须与分页 KV 池共用同一套页表并支持即时回收，且 <span class=\"inline-math\">K</span> 应由识别增量的稳定性而非固定超参决定——识别纠错频繁的语种与口音场景下，把 <span class=\"inline-math\">K</span> 压到 2–4 比追求长推测更稳。</p>\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-27\">二十七 · 推测请求在连续批处理里的位置</h3>\n<p>PredGen 的推测解码不是独立进程，它必须落进一个已经在跑的连续批处理循环里。标准连续批处理每一步从运行队列取活跃序列、拼成一个 batch 做一次前向、按 token 产出后再决定谁退出谁加入。推测请求的特殊性在于它有两次生命：第一次以“未确认前缀”身份进入批，产出候选 token 与 KV；第二次在最终输入确定后以“校验”身份回来，决定保留还是丢弃。调度器若不认识这两种身份，就会把推测请求当成普通请求排进队列，结果要么它占着 batch 槽位等用户说完，要么它在校验时被重新预填整段前缀，两种都把收益吃掉。</p>\n<p>工程上的做法是给推测请求一个显式的生命周期状态机：<code>SPECULATING → PENDING_VERIFY → COMMITTED / ROLLED_BACK</code>。处于 <code>SPECULATING</code> 的序列只允许参与解码步，不允许被抢占出队后重新预填；<code>PENDING_VERIFY</code> 的序列在 batch 里占位但不产生新 token，只等校验器给出公共前缀长度 k。校验是纯前缀比对，代价在前缀长度量级，不进 GPU 前向。真正的代价发生在 <code>ROLLED_BACK</code>：分歧点之后的 KV 全部作废，序列需要从 k 处重新预填并继续解码。设单次推测长度为 K、命中长度为 k，则回退重算的 token 数为 K−k，这部分前向与正常解码同价。因此调度器必须把回退率当作一等指标，而不是只看命中率——命中率是收益侧，回退率才是代价侧。</p>\n<p>具体例子：一路 8k 上下文的对话，用户一句话说到一半，识别流已给出 40 个 token，触发器以 K=16 启动推测。若最终文本与推测前缀在前 12 个 token 一致，则 12 个 token 的 KV 直接复用，只需从第 13 步继续；若识别在第 3 个 token 就纠错，则 13 个 token 的 KV 作废，等于白做一次 16 步解码外加一次增量预填。后者在 batch 里表现为一次突发的前向负载，正是尾延迟的来源。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-28\">二十八 · chunked prefill 与增量预填的叠加</h3>\n<p>chunked prefill 把长预填切成固定大小的块，与解码步混排，目的是压住预填对解码 token 间隔的冲击。PredGen 的增量预填天然就是 chunked 的一种极端形态：每次只对新增的识别 token 做前向，块大小由语音到达节奏决定而非固定值。这带来一个调度上的错配——chunked prefill 的块大小是静态配置，增量预填的块大小是动态的、且可能很小（几个 token）。小块意味着每次前向的算术强度低，GPU 利用率被 launch 开销和权重读取摊薄；但小块也意味着预填不会长时间独占 SM，解码步的间隔更平稳。</p>\n<p>代价可以写成一次前向的有效吞吐：设块大小为 b、权重读取量为 W、单块计算量为 C(b)，则单位 token 的边际成本近似正比于 W/b 加上固定开销。b 越小，W/b 项越主导，预填的算力效率越低。这就是增量预填在低到达率下的隐性代价：它换来了低延迟，但把预填的吞吐效率压到了解码步之下。调度器需要在“等一小段再预填”与“来几个 token 就预填”之间做选择，前者提吞吐、后者提首包。PredGen 的触发逻辑本质上是在做这个选择，只是触发条件是停顿检测而非队列水位。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{W + C(b)}{B_{\\text{mem}}},\\ \\frac{C(b)}{F_{\\text{compute}}}\\right) + \\tau_{\\text{launch}}$$</div>\n<p>其中 B_mem 为显存带宽、F_compute 为有效算力、τ_launch 为 kernel 启动开销。在 Blackwell 上权重读取走 HBM、计算走 tcgen05 路径，b 很小时 T_step 由 W/B_mem 与 τ_launch 共同支配，这就是为什么增量预填必须与解码步合批而不是单独发一次前向——单独发等于把 τ_launch 付两遍。合批的做法是把新增 token 的预填与同一 batch 内其他序列的解码 token 拼在一次前向里，用同一份权重读取摊掉固定开销，代价是预填块的形状被 batch 内其他序列的 token 数牵制。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-29\">二十九 · 优先级、抢占与 KV 的回收边界</h3>\n<p>实时语音交互的 SLO 是首包延迟，不是平均吞吐。这意味着调度器不能只用 FCFS 或公平轮转，必须给“即将发声”的序列更高优先级。PredGen 的推测请求在 <code>PENDING_VERIFY</code> 状态时优先级最高——它离首包只差一次校验和几步解码；而处于 <code>SPECULATING</code> 的请求优先级应低于已确认的活跃解码请求，因为它的产出尚未确定，抢占它损失的只是冗余算力，抢占已确认请求损失的是用户可感知的延迟。</p>\n<p>抢占的代价集中在 KV 上。被抢占的序列要么换出到主机内存再换回，要么丢弃重算。对推测请求而言，<code>SPECULATING</code> 阶段的 KV 是“可能作废”的资产，换出的性价比极低——换出再换回的开销可能超过重新推测。合理的策略是：<code>SPECULATING</code> 序列在显存紧张时直接丢弃，由触发器在下次增量到达时重建；<code>PENDING_VERIFY</code> 与 <code>COMMITTED</code> 序列才值得换出。这条边界把 KV 管理的粒度从“序列”细化到“生命周期状态”，是 PredGen 落到调度层最实质的改动。</p>\n<p>具体例子：GB200 NVL72 单机架内多路会话并发，显存被 KV 占满时，若把 20 路 <code>SPECULATING</code> 序列全部换出，换出带宽与换回延迟会直接推高这些会话的首包；改为丢弃并在下一时间片重建，代价是每路一次 K 步的冗余解码，但换出带宽归零。前者伤尾延迟，后者伤算力效率，选择取决于当前 batch 的算力余量而非显存余量——这是与纯 KV 分页策略不同的判断依据。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-30\">三十 · 分离式预填/解码下的推测归属</h3>\n<p>分离式部署把预填节点与解码节点拆开，预填节点吃长上下文、解码节点吃低延迟 token 间隔。PredGen 的推测解码横跨两个阶段：推测时的增量预填在预填侧，推测出的 token 与 KV 要传给解码侧做后续解码，校验后的回退又可能把序列打回预填侧。这产生一个归属问题——推测产生的 KV 存在哪一侧？若存在解码侧，预填侧对新增 token 的前向需要把 KV 传过去，传输量随前缀长度增长；若存在预填侧，解码侧每步都要拉 KV，token 间隔被互联带宽支配。</p>\n<p>工程判断是让推测 KV 跟随其生命周期：<code>SPECULATING</code> 阶段 KV 留在预填侧，因为此时前缀还在增长、增量预填还在发生；校验命中后把 k 个 token 的 KV 一次性搬到解码侧，搬运量与 k 成正比而非与总前缀成正比，这正是增量预填“代价与新增 token 数成正比”的性质在传输上的对应。回退时解码侧丢弃分歧点之后的 KV，只把公共前缀的 KV 留在原地，避免反向搬运。NVLink 5 的机架内带宽让这种一次性搬运可行，但跨机架的 NIXL 传输会把 k 的大小变成延迟变量——k 越大，搬运越久，首包越晚，这与“命中越多越好”的直觉相反，因为命中的收益是省解码步，代价是搬 KV。</p>\n<div class=\"formula\">$$T_{\\text{handoff}} = \\frac{k \\cdot S_{\\text{kv}}}{B_{\\text{link}}} + \\tau_{\\text{proto}},\\quad \\text{净收益} = T_{\\text{decode}}(K-k) - T_{\\text{handoff}}$$</div>\n<p>其中 S_kv 为单 token KV 字节数、B_link 为互联带宽、τ_proto 为传输协议开销。只有当省下的 K−k 步解码时间超过搬运时间时，跨节点推测才划算。这解释了为什么 PredGen 的推测长度不能盲目加大：K 增大提高命中概率，但也提高单次搬运的 k 上限，在窄带宽链路上净收益可能转负。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-31\">三十一 · 尾延迟的压法：从分位数到触发阈值</h3>\n<p>首包延迟的 SLO 通常卡在 P99 而非均值，因为语音交互的卡顿感知由最慢的那几次决定。尾延迟的来源在 PredGen 场景下有三处：识别纠错导致的整体回退、batch 内长预填块对解码步的挤占、以及校验后 KV 搬运的排队。三者都表现为“偶发的一次长等待”，均值调度看不见它们。</p>\n<p>压尾延迟的手段是把触发阈值从固定改为自适应。固定 K 在识别稳定时命中率高、在识别抖动时回退率高，后者直接制造尾延迟。自适应策略以近期命中率为反馈：命中率低于阈值时缩短 K 甚至暂停推测，把算力还给已确认请求；命中率高时适度加长 K 换取更多首包提前量。这不是调参技巧，而是把推测从“无条件预计算”改成“有条件预计算”，让冗余算力只在期望收益为正时支出。代价是触发器需要维护滑动窗口的命中统计，状态管理本身有开销，但相比一次全量回退的前向便宜得多。</p>\n<p>另一个压法是给回退路径留专用余量。回退重算的 token 数 K−k 是突发的，若与正常解码共享同一 batch 配额，突发会挤占其他序列的 token 间隔，把尾延迟扩散到无关会话。做法是在 batch 组装时给回退请求预留固定槽位，代价是常态下这部分算力闲置，换来的是尾延迟不被传染。具体例子：一个 32 路并发的语音对话服务，若每路回退概率为百分之几量级，预留一到两个回退槽位即可吸收绝大多数突发，而无需为最坏情况配置整批余量。</p>\n<p>尾延迟的度量也要跟着改。只看首包延迟均值会掩盖回退突发，应同时记录回退率、单次回退重算的 token 数分布、以及校验后 KV 搬运的排队时长。这三个量共同决定 P99 首包，缺一个就无法定位尾延迟来自推测长度、识别稳定性还是互联带宽。在 Blackwell 档位上，NVFP4/FP8 的数值一致性还会影响校验稳定性——量化误差可能让推测前缀与最终前缀在数值上出现本不该有的分歧，抬高回退率，这条路径必须在压尾延迟时一并监控，而不能假定校验是纯文本比对、与精度无关。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-32\">三十二 · 推测窗口与批调度的耦合边界</h3>\n<p>PredGen 的推测发生在输入阶段，这使它与连续批处理天然冲突：推测 token 在最终前缀确定前不能算作“已完成请求”，却已占用 KV 槽位与解码步。设并发会话数为 $N$，单次推测长度为 $K$，命中率为 $h$，则每轮调度中真正可计入有效吞吐的 token 数为 $N\\cdot K\\cdot h$，而实际执行与占显存的是 $N\\cdot K$。当 $h$ 偏低时，批内有效工作量被稀释，连续批处理的 token/s 指标虚高而首包延迟不降。工程上应把推测请求放入独立优先级队列，与已确认前缀的解码请求分开组批，避免回退重算污染主批的调度节奏。</p>\n<p>chunked prefill 在这里的角色是双面的。增量预填只对新增 token 做前向，代价与新增量成正比，这本身契合 chunked prefill 的分片思想；但推测触发点若落在一次 chunk 边界之外，就会迫使引擎在未完成的分片上插入解码步，打乱 prefill/decode 混批的比例。可行做法是把推测触发绑定到 chunk 完成事件，令每次推测只消费已稳定的前缀分片，从而把校验成本压到前缀比对级别，而非整段重算。</p>\n<div class=\"formula\">$$T_{\\text{p95}}\\approx T_{\\text{prefill}}+K(1-h)\\,T_{\\text{step}}+\\frac{K h}{B_{\\text{eff}}}\\,T_{\\text{step}}$$</div>\n<p>上式给出尾延迟的粗略结构：$B_{\\text{eff}}$ 为有效批内并发，回退项 $K(1-h)$ 是纯浪费且直接落在 p95 上。分离式预填/解码可缓解这一项——把推测与校验放在预填侧实例，解码侧只接收已确认的 KV，回退重算不占用解码实例的批槽。代价是 KV 需经 NVLink 5 或 NIXL 跨实例搬运，搬运量正比于命中长度，带宽成为新的约束。具体例子：一句话中途识别纠错一次，前缀在分歧点整体失效，长推测 $K$ 越大回退越重，此时应缩短 $K$ 并提高触发频率，用多次短推测换稳定性。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>调度对策</th></tr></thead><tbody><tr><td>识别纠错破坏前缀一致</td><td>回退重算，p95 抬升</td><td>缩短 K、绑定 chunk 边界</td></tr><tr><td>低命中率长推测</td><td>KV 槽位与解码步浪费</td><td>推测独立队列、限并发</td></tr><tr><td>温度采样状态不一致</td><td>校验失效、分布偏离</td><td>固定随机数流、按请求隔离</td></tr></tbody></table>\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-33\">三十三 · 切分策略：从单卡放不下到多卡并行</h3>\n<p>PredGen 的推测解码本身是单模型前向，但当模型规模超出单卡显存、或单卡解码吞吐撑不住并发会话时，推理必须切分。Blackwell 档位上四种切分对应四种不同的通信形态，代价结构完全不同。张量并行（TP）把每层权重按列或行切开，每个 token 的前向需要在每层做两次 All-Reduce 把部分和拼回完整激活；流水并行（PP）把层段分到不同设备，激活以点对点方式在 stage 间传递，气泡大小由微批调度决定；专家并行（EP）把 MoE 的专家分散到多卡，每个 token 经路由后被发往持有目标专家的设备，形成 All-to-All；数据并行（DP）复制权重、切分请求，只在梯度场景需要通信，推理侧几乎零通信但显存被复制。对 PredGen 而言，TP 是最常见的选择——推测解码要在极短时间内完成若干 token 的前向，单卡算力不够时 TP 是唯一不引入路由不确定性的扩展方式。代价是：TP 度每翻一倍，每层两次 All-Reduce 的通信量随之翻倍，而 All-Reduce 的延迟在小消息下由固定开销主导，在推测这种短前向里固定开销占比极高。</p>\n<p>通信量可以写成显式表达式。设隐藏维度为 <i>d</i>、批内 token 数为 <i>B</i>、精度字节数为 <i>s</i>、TP 度为 <i>N</i>，则每层 All-Reduce 单卡收发量为：</p>\n<div class=\"formula\">$$V_{\\text{AR}} = 2 \\cdot (N-1)/N \\cdot B \\cdot d \\cdot s$$</div>\n<p>Ring All-Reduce 的时延近似为 <i>2(N−1)/N · B·d·s / BW + 2(N−1)·t<sub>hop</sub></i>，第二项是每跳固定延迟，在 <i>B</i> 很小（推测解码通常只解几个 token）时它压过第一项。这就是推测解码在 TP 下的核心矛盾：它天生是小批量、低延迟的工作负载，恰好落在通信固定开销最不划算的区间。具体例子：一个 70B 级模型在 TP=8 下每层 All-Reduce 的固定跳延迟若为微秒量级，几十层累加就是数十微秒到上百微秒，而单步解码的计算时间同样在百微秒量级——通信几乎吃掉一半时间预算。PredGen 的收益来自把解码提前到输入窗口，但若每步解码都被 All-Reduce 拖住，提前量会被通信开销侵蚀。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-34\">三十四 · NVLink 5 与 NVSwitch：域内带宽的物理边界</h3>\n<p>Blackwell 的机架内互连是这一层切分能否成立的前提。GB200/GB300 NVL72 把 72 颗 GPU 置于同一 NVLink 域，NVLink 5 提供每 GPU 双向高带宽，NVSwitch 负责全互联交换，使任意两卡之间的通信跳数为一。这意味着 TP=8 甚至 TP=16 的 All-Reduce 可以全部落在 NVLink 域内，不必经过 InfiniBand 或以太网。工程判断很直接：TP 度应尽量不超过单个 NVLink 域的规模，一旦跨域，All-Reduce 的带宽骤降、跳数上升，小消息延迟恶化一个量级。对 PredGen，推测触发是突发性的——用户停顿检测到就立刻启动一次短程解码，这类突发小消息在跨域链路上会被固定延迟放大，收益归零。</p>\n<p>NVSwitch 的价值还在于多播与聚合效率。All-Reduce 在 NVSwitch 上可退化为先 Reduce-Scatter 再 All-Gather，交换机内部完成聚合，避免 Ring 的多跳累加。但即便在 NVSwitch 上，延迟也不是零：每次交换有固定穿越成本，消息越小摊销越差。因此 TP 的通信代价不是带宽问题而是延迟问题——带宽足够，延迟不够。这决定了优化方向：不是提高带宽利用率，而是减少通信次数与消息粒度。具体机制上，可以把每层两次 All-Reduce 合并为一次（例如把行并行与列并行的通信在层边界融合），或在推测解码时把多个候选 token 打包成一次前向以减少 All-Reduce 次数。代价是打包会增大单次消息体积，在带宽充裕而延迟敏感的 NVLink 域内，这是划算的交换。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-35\">三十五 · All-to-All 与 EP：路由不确定性的代价</h3>\n<p>EP 用于 MoE 模型，通信形态是 All-to-All：每个 token 被路由到若干专家，发往持有该专家的设备，算完再发回。与 All-Reduce 不同，All-to-All 的消息大小不均匀——热门专家收到的 token 多，冷门专家少，形成负载倾斜。这种倾斜在推测解码下被放大：推测生成的候选 token 分布与真实分布存在偏差，路由结果可能更集中，导致部分设备成为热点，All-to-All 的完成时间由最慢链路决定。对 PredGen 的直接影响是，推测阶段的 All-to-All 延迟不可预测，命中率高的推测会走热专家路径，命中率低的推测走冷路径，两条路径的通信时间不同，使首包延迟的方差变大。</p>\n<p>工程上的缓解手段是容量因子与 token 丢弃策略，但推理侧不能丢 token（会改变输出分布，违反无损加速的前提），只能靠冗余专家或重排。另一个机制是把 All-to-All 与计算重叠：在等待远端专家返回时，本地先做非专家部分的前向。这要求引擎具备细粒度的流水调度能力，代价是显存中同时驻留多份中间激活，KV 缓存与激活竞争同一块 HBM。在 B200/B300 的显存约束下，重叠深度受限于激活占用，不能无限加深。定性地说，EP 的通信瓶颈不在带宽而在尾部延迟与负载均衡，推测解码的低批量特性让尾部延迟更难被平均掉。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-36\">三十六 · PP 与 DP：气泡与复制的取舍</h3>\n<p>PP 把层段切开，stage 间只传激活，通信量远小于 TP 的 All-Reduce，但引入流水气泡。气泡比例近似为 <i>(P−1)/(M+P−1)</i>，<i>P</i> 为 stage 数、<i>M</i> 为微批数。推测解码的微批数很小（一次推测只有几个 token），<i>M</i> 接近 1 时气泡比例接近 <i>(P−1)/P</i>，几乎全程空转。这是 PP 在低延迟推理中的致命伤：它适合大批量吞吐场景，不适合 PredGen 这种短前向、低批量的突发解码。除非把推测长度 K 调大以增加微批数，但 K 增大会增加低命中率下的浪费，两者互相牵制。因此 PP 在 PredGen 部署中通常只作为显存兜底手段，而非延迟优化手段。</p>\n<p>DP 在推理侧几乎无通信，每个副本独立服务请求，代价是权重与 KV 缓存被完整复制。对 PredGen，DP 的价值在于横向扩展并发会话数：每个副本独立做推测与校验，互不干扰，命中率不受其他会话影响。显存代价是 N 倍复制，在 NVL72 机架上意味着每卡都要留出完整 KV 空间，压缩了单副本可支持的并发长度。工程判断：当单副本吞吐已满足 SLO、瓶颈在并发会话数时用 DP；当单请求延迟不达标时用 TP；两者可以叠加，但 TP×DP 的乘积受 NVLink 域大小与显存双重约束。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-37\">三十七 · NIXL 传输与分离式部署的通信面</h3>\n<p>分离式预填/解码把预填与解码放到不同 GPU 池，KV 缓存需要跨节点搬运，这时 NIXL 成为传输层。NIXL 提供点对点、低开销的显存到显存传输抽象，支持 RDMA 与 NVLink 路径，把 KV 块的搬运从框架层解耦。对 PredGen，分离式部署的意义在于：推测解码发生在输入阶段，预填负载突发且与解码负载形态不同，把两者分开可以让推测引擎独占低延迟资源，而解码池按吞吐优化。代价是 KV 传输成为新的瓶颈项——每个被接受的推测 token 的 KV 要么在推测侧生成后搬到解码侧，要么在解码侧重算。搬运量正比于命中长度 k 与每 token KV 字节数，传输延迟正比于 k 与链路带宽。</p>\n<p>这里有一个与校验机制的耦合点：校验器比对的是 token 序列，但复用的是 KV。若 KV 在传输过程中因精度转换（例如 NVFP4/FP8 存储）发生数值偏移，校验通过的 token 其 KV 可能与重算结果不完全一致，长上下文下误差累积会改变输出分布。因此分离式部署下，KV 传输应保持与计算一致的精度，或在传输后做一致性抽检。NIXL 的零拷贝路径能减少中间缓冲，但精度一致性仍需框架层保证。通信成为瓶颈的判据可以写成：当 <i>k · KV<sub>token</sub> / BW<sub>link</sub> > T<sub>recompute</sub>(k)</i> 时，搬运不如重算，此时应放弃跨池复用、在解码侧重算命中部分。这个不等式是分离式 PredGen 部署的核心工程判断。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-38\">三十八 · 通信何时成为瓶颈：三个判据</h3>\n<p>把上述分析收敛为可操作的判据。第一，消息粒度判据：当单次集合通信的消息体积小于带宽延迟积（<i>BW × t<sub>hop</sub></i>）时，延迟主导，增大 TP 度只会线性增加固定开销而不提升有效算力。推测解码的批量天然小，这条判据几乎总是成立，因此 TP 度应取满足显存与单步算力需求的最小值，而非越大越好。第二，域边界判据：TP 组跨越 NVLink 域时，All-Reduce 带宽与跳数同时恶化，此时应改用 PP 或 DP 扩展，或把 TP 限制在域内、用 DP 做域间扩展。第三，复用经济性判据：分离式部署下，KV 搬运时间超过重算时间时，命中复用失去意义，应退回本地重算。三条判据共同指向一个结论：PredGen 的通信优化不是追求更大带宽，而是把通信限制在最小域内、把消息打包到延迟可摊销的粒度、并在搬运与重算之间做显式比较。</p>\n<p>具体到推测触发的一次执行：触发器启动，引擎对当前前缀做增量预填（新增 token 数少，TP 下 All-Reduce 消息极小、延迟主导），随后解码 K 个候选 token（每步一次 All-Reduce，K 步累加固定开销），校验后命中 k 个 token 的 KV 被保留。整条路径上通信开销与 K 成正比、与命中率无关，而收益与 k 成正比。因此净收益的条件是 <i>k · T<sub>step</sub> > K · T<sub>comm</sub></i>，即命中节省的解码步数所省下的时间要超过 K 步通信的固定开销。命中率低时 k 小、右侧不变，不等式翻转，推测反而拖慢首包——这正是通信视角下 PredGen 收益边界的定量表达，也是部署时必须用实测命中率与实测 All-Reduce 延迟代入的判据，而非凭推测长度拍脑袋。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-39\">三十九 · 切分方式决定推测窗口能否被并行摊薄</h3>\n<p>PredGen 的推测解码发生在输入阶段，其并行形态与常规解码服务不同：推测长度 K 内的 token 仍是自回归串行，但多路并发会话的推测可以彼此独立地填满 SM。真正决定通信是否成为瓶颈的，是切分维度而非推测本身。TP 把每层矩阵乘切到多卡，每次前向都要 All-Reduce 激活，通信量与隐藏维度和 batch 成正比，延迟敏感的首包路径上任何一次跨卡同步都直接计入首包；EP 把 MoE 专家分散，每 token 需 All-to-All 路由，专家负载不均时尾部延迟放大；PP 把层分段，微批在流水线间传递激活，气泡在推测这种短前向里占比更高；DP 复制权重、只切请求，是推测会话最友好的形态——单路推测无需跨卡通信，代价是权重显存按卡重复。工程判断很直接：把首包关键路径放在单卡或单 DP 副本内完成，把 TP/EP 留给吞吐侧的长解码。</p>\n<p>通信代价可用一个粗略的 roofline 判断：设单次 All-Reduce 传输量为 \\(V\\)，互联带宽为 \\(B\\)，则同步开销 \\(t_{\\text{comm}}\\approx 2V/B\\)（环形算法下与卡数近似无关，只随消息大小线性增长）。NVLink 5 与 NVSwitch 提供的是高带宽、低跳数的域内互联，使小消息 All-Reduce 的固定延迟被压得很低；一旦跨节点，NIXL 之类的传输层要做 RDMA 与显存注册，单次传输的启动开销远高于域内，KV 与激活的搬运就不再免费。对 PredGen 而言，增量预填只处理新增 token，单次前向的消息很小，此时固定开销占比上升，通信从“带宽受限”转为“延迟受限”，这是切分过细反而拖慢首包的根因。</p>\n<table class=\"mini\"><thead><tr><th>切分</th><th>每步通信</th><th>对推测首包的影响</th></tr></thead><tbody><tr><td>DP</td><td>无（请求独立）</td><td>最优，权重显存重复</td></tr><tr><td>TP</td><td>每层 All-Reduce</td><td>同步次数多，小消息延迟主导</td></tr><tr><td>EP</td><td>每 token All-to-All</td><td>负载不均放大尾部</td></tr><tr><td>PP</td><td>段间激活传递</td><td>短前向下气泡占比高</td></tr></tbody></table>\n<p>失效条件集中在两处。其一是命中率低时的回退重算：分歧点之后全部丢弃，若此时推测结果已跨卡完成 TP 前向，浪费的不只是算力，还有已支付的通信时间，回退越频繁，通信开销越被重复计费。其二是流式识别纠错破坏前缀一致性，使整段推测作废，而 KV 缓存管理还要处理跨卡 KV 的失效与重分配。温度采样下复用推测 token 需保持随机数状态一致，否则输出分布偏离，这一点在多卡切分下更难保证——不同卡的采样路径必须共享同一随机流。可迁移到分离式预填/解码的启示是：把校验与 KV 复用放在同一互联域内，避免命中判定后再跨节点搬运 KV；推测长度 K 应按互联档位自适应，域内可放大，跨节点应收缩，把冗余算力留在本地。</p>\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-40\">四十 · 精度塌陷：校验通过但输出已偏</h3>\n<p>PredGen 的校验器只做最长公共前缀比对，它保证的是“token 序列一致”，并不保证“数值路径一致”。在 Blackwell 上启用 NVFP4/FP8 后，推测阶段与校验阶段若走了不同的量化 kernel、不同的累加顺序，或 tcgen05 MMA 的缩放因子在两次前向中被重新量化，前缀比对仍可能通过，而命中复用的 KV 已带有与真实前向不同的舍入残差。这类失败在单请求上表现为音质毛刺、韵律漂移，在批内则表现为同一前缀在不同 batch 位置产出不同续写。</p>\n<p>诊断手段是把校验从“字符串相等”升级为“数值指纹相等”：对每个推测 token 记录其 logits 的 top-k 索引与对应概率的定点化摘要，命中时要求摘要逐位相同，否则降级为未命中。代价是每 token 一次额外的摘要计算与比较，在解码热路径上增加的是寄存器压力而非显存带宽，属于可接受开销。更根本的机制约束是：推测引擎与校验引擎必须绑定同一份量化配置与同一 kernel 选择表，任何一侧的 autotune 结果变化都要使已有 KV 失效。</p>\n<div class=\"formula\">$$\\delta_{\\text{num}}=\\max_{i\\in[1,k]}\\left|\\,\\text{logits}_{\\text{spec}}(i)-\\text{logits}_{\\text{final}}(i)\\,\\right|_2,\\quad \\text{accept}\\iff \\delta_{\\text{num}}&lt;\\epsilon$$</div>\n<p>温度采样下的随机数状态是另一条塌陷路径：推测 token 在采样时消耗了 RNG 流，若校验阶段从分歧点重算却不回滚 RNG 状态，后续 token 的分布就与原模型偏离，输出不再是“无损加速”。工程上应把 RNG 状态与 KV 一起纳入缓存条目，回退时同步回滚。具体例子：一个 8 路并发的语音会话，其中一路因识别纠错触发回退，若 RNG 未回滚，该路后续整句的采样轨迹都与单请求基线不同，A/B 对比时会被误判为模型问题。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-41\">四十一 · OOM：KV 碎片与推测预留的叠加</h3>\n<p>PredGen 的显存压力不是稳态的，而是随推测长度 K 与并发会话数相乘跳变。每个活跃会话在推测阶段要预留 K 个 token 的 KV 槽位，命中则转正、未命中则整段释放。若分配器按固定块切分，反复的“预留—释放”会制造外部碎片，长会话累积后可用大块减少，最终在总占用未达上限时触发 OOM。Blackwell 的 HBM 容量虽大，但 GB200 NVL72 上多实例共享显存池，单实例的碎片会通过池化放大。</p>\n<p>定位方法是把 KV 占用拆成三段监控：已提交 token 的 KV、推测预留的 KV、碎片空洞。三者之和才是真实占用，只看前两项会低估。回滚策略是给推测预留设硬上限——当预留总量超过阈值时，推测触发器直接跳过本轮推测，退化为普通增量预填，用首包延迟换稳定性。这是静默降级的一种，必须打点上报，否则容量规划会把降级后的延迟当成常态。</p>\n<table class=\"mini\"><thead><tr><th>占用段</th><th>来源</th><th>诊断信号</th><th>处置</th></tr></thead><tbody><tr><td>已提交 KV</td><td>已接受 token</td><td>随会话时长单调增长</td><td>按会话上限驱逐</td></tr><tr><td>推测预留</td><td>K × 活跃会话</td><td>随触发频率抖动</td><td>预留超阈值则跳过推测</td></tr><tr><td>碎片空洞</td><td>预留释放不连续</td><td>大块分配失败率上升</td><td>块大小分层或整理</td></tr></tbody></table>\n<p>具体例子：某会话说话时长拉长，前缀持续增长，增量预填的代价与新增 token 数成正比而非总前缀长度，这本身是省的；但若每轮都触发长度 K 的推测且命中率低，预留段反复占用又释放，碎片空洞在数十轮后成为 OOM 的主因，此时降低 K 比增大显存更有效。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-42\">四十二 · 批抖动：命中率随 batch 位置漂移</h3>\n<p>连续批处理下，推测命中不是请求的固有属性，而是批内位置的函数。同一前缀在不同 batch 组成、不同 padding 布局下，增量预填的 kernel 选择与规约顺序会变，数值指纹随之漂移，命中判定在边界情形下翻转。结果是吞吐曲线出现抖动：批大小增大本应摊薄权重读取，但命中率下降使回退重算的比例上升，净吞吐反而回落。这种抖动在 SLO 监控上表现为 p99 首包延迟的锯齿。</p>\n<p>诊断需要把命中率按 batch 大小、按批内槽位、按前缀长度分桶统计，而不是只看全局均值。全局命中率掩盖了“小批高命中、大批低命中”的结构。定位到具体桶后，处置是给校验加容差带或对边界 token 强制重算，用少量确定性换吞吐稳定。代价是每次强制重算多一次前向，但避免了整批的命中翻转。</p>\n<div class=\"formula\">$$H(b)=\\frac{1}{N_b}\\sum_{j\\in\\text{batch}(b)}h_j,\\quad \\frac{\\partial \\text{TPOT}}{\\partial b}&gt;0\\ \\text{当}\\ \\frac{\\partial H}{\\partial b}&lt;0$$</div>\n<p>具体例子：批从 4 扩到 16 时，长前缀请求被挤到批尾，其推测 KV 与短请求共享同一块预填 buffer，规约顺序改变导致首个推测 token 的概率摘要不再逐位相同，该请求整段回退；单看这一路延迟翻倍，但全局均值只上升一点，若不按槽位分桶就找不到根因。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-43\">四十三 · 尾延迟：回退重算的长尾</h3>\n<p>PredGen 的收益分布是双峰的：命中路径省下 k 步解码，未命中路径不仅白做 K 步推测，还要从分歧点重算，且分歧越早重算越长。首包延迟的 p50 因命中而下降，p99 却可能因少数整段回退而抬升。语音交互的 SLO 恰恰卡在尾部分位，均值改善不能抵消尾部恶化。</p>\n<p>监控上要把“推测轮次”“命中长度 k”“回退重算 token 数”三者做成联合直方图，尾延迟的贡献可以直接归因到 k=0 的桶。定位到该桶后，判断是识别纠错导致还是数值漂移导致：前者表现为分歧点靠前且与识别修订时间戳对齐，后者表现为分歧点随机分布。处置不同——前者调触发时机，避开识别纠错高发窗口；后者修量化一致性。</p>\n<p>具体例子：用户在说话中途自我纠正，识别流先给出错误词再回填正确词，推测前缀与最终前缀在首个 token 即分歧，K 步推测全部作废，重算从零开始，该请求的首包延迟高于不做推测的基线。这类请求占比不高但足以主导 p99，因此推测触发器应检测识别结果的修订信号，在修订后短暂关闭推测。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-44\">四十四 · 静默降级：收益消失而不报警</h3>\n<p>最危险的失败不是崩溃，而是系统悄悄退化成普通解码而监控仍显示健康。三种典型静默降级：推测触发器因预留超限被跳过、校验因数值容差被放宽到恒真、批调度因 OOM 风险把推测请求单独串行化。三者都让首包延迟回到基线，但请求成功率、错误率这些常规指标毫无变化。</p>\n<p>对策是把“推测实际生效”做成一级指标：单位请求的推测轮次、接受 token 占比、回退重算 token 占比、推测节省的解码步数。这四个量中任何一个长期趋零，就应触发告警而非等待延迟指标恶化。回滚路径要预先定义：关闭推测触发器、固定 K 为保守值、回退到纯增量预填三档，按告警级别逐级切换，且切换本身要记录版本与时间戳，便于事后归因。</p>\n<ul><li>一级信号：接受 token 占比跌破阈值，说明命中率塌陷，先查识别一致性与量化配置。</li><li>二级信号：推测轮次趋零，说明触发器被容量逻辑压制，查预留上限与碎片。</li><li>三级信号：回退重算 token 占比上升而命中率不变，说明批布局漂移，查分桶统计。</li></ul>\n<p>具体例子：一次量化配置更新后，校验摘要的比较逻辑因 kernel 版本变化而恒不相等，系统每轮都回退，但请求全部成功、延迟只轻微上升，直到容量规划按旧加速比扩容才发现算力被冗余推测吃掉。这类问题的定位只能靠“接受 token 占比”这一条指标，延迟分位数不够敏感。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-45\">四十五 · 推测失效的五类现场：从命中率塌陷到静默降级</h3>\n<p>PredGen 的净收益全部押在“推测前缀与最终前缀的最长公共前缀长度 k”上，因此失败模式几乎都可以还原为 k 的分布偏移。第一类是精度塌陷：流式识别在用户说话中途发生纠错（同音替换、断句回改、数字与专名后置修正），使推测前缀在首个 token 即分歧，命中长度 k=0，整段推测的 KV 与输出全部作废，回退到真实前缀重算。此时系统付出的代价不是“没赚到”，而是实打实的负收益——多了一次短程自回归解码的前向与 KV 写入，外加一次从分歧点开始的重新预填。用有效解码步数刻画：<div class=\"formula\">$$L_{\\text{eff}}=\\frac{T_{\\text{decode}}}{1+\\alpha\\cdot h},\\quad h=\\frac{|P_{\\text{spec}}\\cap P_{\\text{final}}|}{|P_{\\text{spec}}|}$$</div>当 h 因纠错跌到接近 0，分母趋近 1，冗余算力直接叠加到首包延迟上；而推测长度 K 越大，单次失效浪费的 KV 显存与解码步数越多，这就是“长推测在低命中率下反噬”的量化来源。</p>\n<p>第二类是 OOM 与批抖动。推测产生的候选 KV 在最终输入确定前必须驻留，属于“未确认缓存”，与已确认前缀的 KV 争夺同一块显存池；并发会话数上升时，未确认 KV 的峰值占用随 K 与并发线性增长，而材料未给出硬件档位与批大小，KV 边界无法定量，只能靠运行时观测。批抖动则来自推测触发器的非周期节拍：停顿检测或增量到达触发一次推测，会把连续批处理中稳定的 decode 批切成“预填+短解码”的混合批，token 间延迟（ITL）出现锯齿，尾延迟 p99 被少数长推测会话拉高。第三类是尾延迟与静默降级：当校验器发现分歧率持续偏高，工程上常见的自保动作是缩短 K、降低触发频率甚至关闭推测——系统仍能出声，但首包延迟悄悄回到无推测基线，监控上只表现为“命中率下降、冗余算力归零”，若不单独埋点，这种降级会被误读为负载变轻。</p>\n<p>诊断要按“前缀一致性—KV 生命周期—批形态”三层下钻，而不是只看端到端延迟。第一层埋点最长公共前缀长度 k 的分布与分歧位置（首 token 分歧 vs 中段分歧），前者指向识别纠错，后者指向增量预填的切分边界；同时记录温度采样下随机数状态是否与推测时一致，否则复用 token 会偏离原模型分布，属于必须回滚的数值一致性故障。第二层跟踪未确认 KV 的峰值占用、回退重算频率与缓存碎片率，把 OOM 从事后崩溃变成事前水位告警。第三层对比推测开启与关闭两套批形态下的 ITL 分位数，识别批抖动来源。回滚策略应是分级而非一刀切：先降 K 与触发阈值，再退到“只推测不预填”的保守档，最后关闭推测并保留增量预填；每一级都要以命中率与首包延迟分位数为判据，而不是以平均延迟为判据——平均值会把少数命中极好的会话掩盖掉多数失效会话的代价。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>识别纠错致前缀分歧</td><td>k 分布左移、首 token 分歧率升</td><td>冗余解码+重算预填，首包延迟反升</td><td>降 K、推迟触发至停顿点</td></tr><tr><td>未确认 KV 堆积</td><td>KV 水位随并发线性抬升</td><td>OOM 风险、批容量被压缩</td><td>限并发、设未确认 KV 上限</td></tr><tr><td>触发节拍扰动批</td><td>ITL 锯齿、p99 抬升</td><td>吞吐下降、尾延迟劣化</td><td>推测与 decode 批隔离调度</td></tr><tr><td>随机数状态不一致</td><td>复用 token 与基线分布偏离</td><td>输出正确性受损（非无损）</td><td>立即回滚推测路径</td></tr></tbody></table>\n<p>工程判断落在触发时机而非推测长度上：识别增量到达节奏不稳定时，固定 K 与固定阈值都无法最优，应以“距上次纠错的时间窗”和“当前前缀的稳定 token 比例”作为触发门控，把推测预算花在低纠错概率的窗口里。Blackwell 平台上还需把 NVFP4/FP8 的数值一致性纳入校验链——量化后的前向若使同一前缀产生不同 logits，最长公共前缀比对本身就会失真，此时命中率指标不再可信，必须用未量化的参考前向做抽样校验。这套监控与回滚逻辑的可迁移性正在于此：它约束的不是某个模型，而是“提前计算”这一动作在流式输入下的失效边界。</p>\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-46\">四十六 · 口径先行：这份材料能支撑什么、不能支撑什么</h3>\n<p>读 PredGen 的实验部分，第一件事不是看它快了多少，而是确认它到底给了哪些可比的量。材料对基准信息的披露是残缺的：没有数据集名称、没有基线系统名称、没有硬件档位、没有量化方案、没有批大小与并发档位、没有加速比与毫秒级延迟数字、没有命中率数值、没有消融细节。这意味着任何“PredGen 在 B200 上把首包延迟降低 N 倍”的说法都不是从这份材料里读出来的，而是外推。作为工程读者，必须把这条边界画死：本工作可被引用的结论是定性的——在实时语音交互场景下，通过在输入阶段做推测解码可以降低首包延迟，收益随命中率与推测长度变化；不可被引用的是任何具体倍数。</p>\n<p>由此产生的读法是“机制可复用、数字不可搬运”。机制层面材料给足了：推测在输入阶段执行、最长公共前缀校验、增量预填只对新增 token 做前向、命中部分复用 KV 与输出、分歧点之后丢弃重算、温度采样需保持随机数状态一致。这些是可以直接映射到 Blackwell 部署决策上的结构性事实。数字层面则必须由读者自己在目标硬件档位上补齐，且补齐的方式要遵循统一口径，否则跨系统比较毫无意义。</p>\n<p>一个具体的口径陷阱：把“首包延迟下降”与“端到端吞吐提升”混为一谈。PredGen 的收益发生在用户仍在说话的时间窗内，这段时间 GPU 本来处于预填空转或低利用率状态，推测解码把空闲算力换成提前完成的解码步。因此它改善的是延迟指标（TTFT 类），而对稳态吞吐（tokens/s per GPU）的影响取决于这段空闲算力是否本可被其他请求占用。在连续批处理下，空闲窗口往往已被别的会话填满，此时推测解码是纯粹的算力抢占，吞吐可能不升反降。这就是为什么本工作必须与批调度策略一起评估，而不能单独报一个延迟数字了事。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-47\">四十七 · 硬件档位：Blackwell 上哪些量会变、哪些不会变</h3>\n<p>材料未给硬件档位，但机制对硬件的敏感点是可以推出来的。推测解码的净收益由两部分构成：命中时节省的解码步数，以及未命中时额外付出的预填与解码算力。前者是延迟收益，后者是算力代价，两者的比值在不同档位上并不相同。在 B200/B300 这类单卡显存与带宽都较宽的档位上，KV 缓存的驻留成本相对低，长推测带来的显存压力更容易被吸收；而在 GB200/GB300 NVL72 这类机架级配置上，真正的约束从单卡显存转向跨卡 KV 传输与一致性校验的通信开销——校验需要最终前缀与推测前缀逐 token 比对，若前缀分散在不同卡的 KV 分片上，比对本身就要走 NVLink 5，这笔开销在单卡场景下不存在。</p>\n<p>精度档位同样改变结论。材料未给量化方案，但 NVFP4/FP8 下推测解码有一个特殊风险：校验依赖原模型对前缀的确定性前向，量化后的前向若在不同 batch 形状或不同 kernel 路径下产生数值抖动，最长公共前缀比对可能在语义等价的 token 上出现分歧，把本可命中的推测判为失效。这不是精度问题本身，而是“确定性”被量化打破的问题。工程判断是：在 FP8 下做推测校验，必须固定前向的 kernel 选择与归约顺序，否则命中率会被数值噪声系统性压低，而这一损失在材料里没有任何数字可以参照。</p>\n<div class=\"formula\">$$\\text{净收益} \\;=\\; \\underbrace{h\\cdot K\\cdot t_{\\text{dec}}}_{\\text{命中节省}} \\;-\\; \\underbrace{(1-h)\\cdot K\\cdot (t_{\\text{pre}}+t_{\\text{dec}})}_{\\text{未命中浪费}} \\;-\\; \\underbrace{c_{\\text{verify}}(K)}_{\\text{校验开销}}$$</div>\n<p>其中 h 为命中率、K 为推测长度、t_dec 为单 token 解码时间、t_pre 为单 token 增量预填时间、c_verify 为校验成本。这个式子说明为什么硬件档位不能省略：t_dec 与 t_pre 的比值由显存带宽与 MMA 吞吐决定，在 tcgen05 与 2-SM MMA 路径上，预填的吞吐远高于逐 token 解码，因此 t_pre 通常远小于 t_dec，未命中浪费主要来自被丢弃的解码步而非预填。这反过来解释了为什么“增量预填只对新增 token 做前向”是必要的——它把未命中代价中的预填项压到与新增 token 数成正比，而不是与总前缀长度成正比。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-48\">四十八 · batch 与并发：延迟收益在批处理下会被稀释</h3>\n<p>材料明确说并发会话数影响 KV 缓存占用与批调度，但未给具体并发档位。这一点必须展开，因为它是 PredGen 数字最难读的地方。单请求视角下，推测解码把空闲算力换成提前解码，首包延迟下降是干净的。但在连续批处理下，一个会话的“用户仍在说话”窗口正是调度器填充其他请求 decode 步的机会。此时推测解码抢占的算力会挤掉别人的 token 产出，系统级吞吐与尾延迟可能恶化。也就是说，PredGen 的收益是 per-request 的，代价是 system-level 的，两者不在同一个口径上。</p>\n<p>可操作的读法是分层报告：第一层报单会话、batch=1 下的首包延迟分布（P50/P90/P99），这是机制本身的收益上限；第二层报固定并发下的系统吞吐与尾延迟，这是工程可部署的收益；第三层报单位请求的冗余算力（被丢弃的推测 token 数除以总生成 token 数），这是成本项。材料只支撑第一层的定性结论，第二三层必须实测。若只报第一层就宣称“加速”，等于把空闲算力的机会成本记为零，这在任何有并发压力的生产环境里都不成立。</p>\n<p>具体例子：设一个会话在用户说话的 2 秒内触发若干次短程推测，每次推测 K 个 token。若命中率高，这些 token 的 KV 直接保留，解码从第 k+1 步继续，首包在输入结束的瞬间即可发出；若同一张卡上还有三个会话正在 decode，这 2 秒内的算力被推测占用，那三个会话的 TPOT 会在这段时间内抬升。调度器若不做优先级区分，尾延迟的恶化会抵消首包收益。这正是把 PredGen 与批调度策略耦合评估的原因，也是分离式预填/解码架构下需要重新分配算力配额的原因。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-49\">四十九 · 指标口径：TTFT、TPOT、吞吐、显存、功耗各自量的是什么</h3>\n<p>PredGen 语境下的“首包延迟”不是标准 TTFT。标准 TTFT 从请求到达算到第一个输出 token，而语音交互里的等待从“用户说完”算起，用户说话期间的时间不计入用户感知的等待。PredGen 的贡献正是把这段不计入等待的时间利用起来，所以它的延迟指标应定义为“输入结束到首 token 发出”的间隔，而不是“请求开始到首 token”。这两个口径混用会让收益看起来被放大或缩小，取决于说话时长。工程上应明确记录 t_input_end 与 t_first_token 两个时间戳，报告其差值分布，而不是笼统报一个 TTFT。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>量的是什么</th><th>PredGen 下的读法</th></tr></thead><tbody><tr><td>首包延迟</td><td>输入结束到首 token</td><td>机制直接改善的量，需按分位数报</td></tr><tr><td>TPOT</td><td>相邻输出 token 间隔</td><td>推测命中段不产生 TPOT，只影响后续解码</td></tr><tr><td>系统吞吐</td><td>单位时间总 token 数</td><td>并发下可能被推测抢占而下降</td></tr><tr><td>KV 显存</td><td>驻留的 KV 字节数</td><td>推测 KV 与命中复用共同抬高峰值</td></tr><tr><td>功耗</td><td>单位时间能耗</td><td>空闲窗口被填满，能效比可能改善也可能恶化</td></tr></tbody></table>\n<p>TPOT 的口径尤其容易读错。推测命中的 token 是提前算好的，它们在输出时不需要再走解码步，因此这些 token 之间的间隔接近于零，把它们计入 TPOT 平均值会人为压低 TPOT，制造“解码变快”的假象。正确做法是把命中段与后续真实解码段分开统计，或者只统计分歧点之后的 TPOT。显存方面，推测 KV 在命中前一直驻留，若 K 较大且并发高，峰值显存会明显高于无推测基线；材料未给具体数字，但机制上这是必然的成本项，需要在容量规划时预留。功耗则取决于空闲窗口原本的利用率：若原本 GPU 在等输入时空转，填满它提升能效；若原本已被其他请求占满，推测是额外能耗。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-50\">五十 · 哪些提升不可比：四类常见的错误外推</h3>\n<p>第一类是把不同说话时长下的首包延迟放在一起比。用户说 1 秒和说 5 秒，可用于推测的窗口长度不同，命中机会不同，首包延迟的绝对值也不同。跨系统比较必须固定输入时长分布，否则一个系统只是碰上了更长的说话窗口就显得更快。第二类是把不同推测长度 K 的结果混报。K 是超参，K 越大命中时节省越多、未命中时浪费越多，净收益是 K 的非单调函数，报一个“加速比”而不说 K 等于没报。</p>\n<p>第三类是把不同识别稳定性下的命中率直接比较。材料指出流式识别纠错会破坏前缀一致性，导致推测整体失效。识别系统的增量稳定性因语言、口音、领域词汇而异，在一个识别纠错频繁的场景里测出的命中率不能搬到另一个场景。第四类是把不同精度档位下的结果等同。NVFP4/FP8 下校验的确定性风险会压低命中率，而材料未给量化方案，任何跨精度比较都缺少控制变量。</p>\n<ul><li>不可比：单会话延迟收益 vs 多并发系统吞吐，二者口径不同，不能互相换算。</li><li>不可比：不同 K 下的加速比，除非同时报告命中率与冗余算力。</li><li>不可比：不同识别稳定性场景的命中率，纠错率是隐藏变量。</li><li>不可比：不同精度档位的校验成功率，确定性未被控制。</li></ul>\n<p>具体例子：一个团队在 B200 上用 FP8 跑 PredGen，batch=1，测得首包延迟明显下降，于是把该数字写进容量规划，假设生产环境 batch=32 时同样受益。这个外推在三处失效：并发下算力被抢占、FP8 校验的确定性未验证、生产输入的识别纠错率未知。正确的做法是把这三个变量作为实验因子，分别测出收益的边界，再决定是否在调度器里为推测解码预留算力配额。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-51\">五十一 · 把数字读成决策：需要补测的最小实验集</h3>\n<p>给定材料的缺口，要在 Blackwell 上落地 PredGen，最小实验集应包含四个维度。其一，固定输入时长分布与识别系统，扫 K 与触发阈值，测首包延迟分位数与冗余算力，画出净收益随 K 变化的曲线，找到拐点。其二，固定 K 与阈值，扫并发档位，测系统吞吐与尾延迟，确认推测抢占的代价是否可接受。其三，在目标精度（NVFP4 或 FP8）下验证校验的确定性，测命中率相对 FP16/BF16 的偏移。其四，在目标硬件档位上测 KV 峰值显存，确认推测 KV 驻留是否触发容量上限。</p>\n<div class=\"formula\">$$K^{*}=\\arg\\max_{K}\\;\\frac{h(K)\\cdot K\\cdot t_{\\text{dec}}-(1-h(K))\\cdot K\\cdot t_{\\text{pre}}}{t_{\\text{dec}}+(1-h(K))\\cdot K\\cdot t_{\\text{dec}}}$$</div>\n<p>这个式子给出 K 的选择逻辑：分子是净节省时间，分母是有效解码时间，h(K) 随 K 增大而下降（推测越长越容易在尾部失配），因此存在一个最优 K。材料未给 h(K) 的形状，这正是必须实测的原因——它同时依赖识别增量稳定性与模型对前缀的确定性，两者都无法从材料推出。工程判断上，宁可取偏小的 K：短推测的未命中代价低，回退重算的 KV 碎片少，在并发场景下对别人的 TPOT 扰动也小；长推测只在识别极其稳定、并发极低的场景里才划算。</p>\n<p>最后落到一个具体机制上：校验器的最长公共前缀比对是整条链路的成本锚点。它决定了命中判定的粒度，也决定了回退重算的起点。若把校验做成逐 token 串行比对，K 较大时比对本身会成为延迟项；若做成前缀哈希或分块比对，则要保证分块边界与 KV 分片边界对齐，否则复用 KV 时会出现跨块拼接的额外拷贝。在 NVL72 这类跨卡 KV 分片的配置上，这个对齐问题直接决定校验开销是走 NVLink 还是走本地显存，是 PredGen 从单卡机制变成机架级机制时必须重新设计的部分。</p>\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-52\">五十二 · 迁移到非语音自回归模型：时间冗余从哪来</h3>\n<p>PredGen 的收益来源不是“投机解码”本身，而是输入阶段存在一段可被利用的<b>时间冗余</b>：用户说话的时间窗口里，前缀在增长，而解码器处于空转。迁移到别的模型时，第一件事是判断这个窗口是否存在、以及窗口内的前缀增长是否可预测。文本输入的对话系统里，用户打字速度远低于语音，前缀增量到达稀疏且停顿不可预测，推测触发器的有效触发次数下降，单次推测的期望收益被摊薄；代码补全场景相反，前缀增长是逐字符的、局部可预测性强，但最终前缀常被编辑操作改写，最长公共前缀校验会频繁在早期分歧。真正的判据是<b>前缀到达速率与最终前缀稳定性的乘积</b>：到达快且纠错少，迁移成立；到达慢或纠错密集，推测窗口被浪费。</p>\n<p>机制上需要改的是推测触发器的判据。原方案以“停顿或增量”触发，迁移到文本流时应改为以<b>增量 token 数与已等待时长的比值</b>触发，即只在单位时间内新增 token 足够多、且剩余等待时间估计超过一次短程解码开销时才启动。伪代码思路：</p>\n<div class=\"formula\">$$\\text{trigger}=\\mathbb{1}\\left[\\frac{\\Delta n}{\\Delta t}&gt;\\rho \\;\\wedge\\; \\hat{T}_{\\text{wait}}&gt;c\\cdot K\\right]$$</div>\n<p>其中 $\\hat{T}_{\\text{wait}}$ 是对输入结束时间的估计，$K$ 为推测长度，$c$ 为单 token 解码代价系数。代价面：文本场景下触发次数少，冗余算力占比低但绝对节省也低；语音场景触发密集，节省显著但 KV 占用峰值高。具体例子：一个语音助手在用户说“帮我订明天……”时已可推测“下午的机票”，而一个文本聊天框里用户只打了“帮我订”，推测窗口尚未形成，强行触发只会产生被丢弃的 KV。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-53\">五十三 · 校验语义的边界：确定性前向是硬前提</h3>\n<p>最长公共前缀校验之所以无损，前提是原模型对同一前缀的确定性前向。迁移到使用温度采样、top-p、beam search 或带惩罚项的解码配置时，复用推测 token 需要随机数状态在推测与最终解码之间保持一致，否则被复用的 token 虽在前缀上一致，其后续分布的采样轨迹已经偏离。工程判断是：<b>校验必须比对 token 序列而非仅比对前缀文本</b>，并且在采样场景下把 RNG 状态作为 KV 复用的一部分一起快照。若框架的解码器把 RNG 状态封装在采样器内部而不暴露，迁移就需要改造采样器接口，这是一笔真实的集成成本，而不是配置项。</p>\n<p>另一个边界是结构化输出与约束解码。带语法约束的解码器在每一步对 logits 做掩码，推测阶段若未施加同一掩码，推测出的 token 可能在最终约束下非法，校验必然失败；若施加了掩码，推测与最终解码的掩码状态需同步推进。代价体现在回退率上：约束越强，推测命中率越低，净收益越接近零。具体例子：JSON 模式下的函数调用生成，推测阶段生成的键名常被最终 schema 拒绝，回退重算把首包延迟拉回基线水平。这类场景应直接关闭输入时推测，或把推测长度压到极短以限制浪费。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-54\">五十四 · 与分离式预填/解码和连续批处理的耦合</h3>\n<p>迁到 Blackwell 上的生产栈时，PredGen 不是独立模块，而是与预填/解码分离（disaggregation）和连续批处理共享同一批 KV 资源。推测产生的候选 KV 在最终输入确定前处于“未确认”状态，若与已确认请求混在同一 KV 池中，会挤占正在解码的请求的显存页，抬高尾延迟。可行做法是给推测 KV 打独立的生命周期标签，设置<b>未确认 KV 的硬上限</b>，超限即丢弃最老的推测分支而非驱逐已确认请求。公式上，单会话的未确认 KV 占用近似为：</p>\n<div class=\"formula\">$$M_{\\text{spec}}\\approx b\\cdot K\\cdot L\\cdot d\\cdot s$$</div>\n<p>其中 $b$ 为分支数，$K$ 为推测长度，$L$ 为层数，$d$ 为隐藏维，$s$ 为每元素字节数。在 NVFP4/FP8 下 $s$ 下降，但校验对数值一致性的敏感度上升：量化后的前向若在推测与最终路径上使用了不同的 kernel 或不同的累加顺序，同一前缀可能产生不同的 token，校验误判为分歧。工程判断是把推测与最终解码绑定到同一量化 kernel 路径，宁可牺牲一点吞吐也不引入数值分叉。</p>\n<p>批调度层面，推测请求是“短、频、可丢弃”的负载，与长解码请求混批会拉低 GPU 利用率。具体例子：在 GB200 NVL72 的一个推理实例上，若把推测请求与长上下文解码请求放进同一连续批，推测请求的频繁抢占使解码请求的 token 间隔抖动，SLO 分位数恶化；把推测请求路由到独立的轻量执行队列、只共享权重不共享批，代价是权重驻留显存翻倍，需按会话密度权衡。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-55\">五十五 · 规模上限：命中率随前缀长度衰减</h3>\n<p>推测长度 $K$ 不是自由参数，其上限由命中率的衰减曲线决定。前缀越长，后续 token 的条件分布越分散，推测与最终前缀在早期分歧的概率越高；一旦首个 token 分歧，整段推测作废。因此有效节省不是线性的，而是随 $K$ 先升后降。设单步分歧概率为 $p$，则长度 $K$ 的推测被完整接受的概率约为 $(1-p)^K$，期望节省步数近似为：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{save}]\\approx\\sum_{i=1}^{K}(1-p)^{i}-\\lambda\\cdot K$$</div>\n<p>其中 $\\lambda$ 为冗余算力折算到延迟上的系数。该式给出规模上限的直觉：当 $p$ 随前缀增长而上升时，最优 $K$ 存在内点，且随 $p$ 增大而迅速缩小。工程上应做<b>自适应 $K$</b>：用近期会话的实测命中率估计 $p$，把 $K$ 压到 $\\mathbb{E}[\\text{save}]$ 的最大值附近，而非固定超参。代价面：自适应需要在线统计与反馈回路，增加调度器复杂度；收益面：在识别纠错密集的会话里避免长推测的显存与算力反噬。具体例子：多说话人、口音重的语音输入，识别增量纠错频繁，$p$ 高，固定 $K$ 的配置会把首包延迟推高到基线之上，而自适应 $K$ 退化为短推测后仍能保留小幅收益。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-56\">五十六 · 不适用的场景与判断清单</h3>\n<p>三类场景应明确判定不适用。其一，<b>输入不可增量</b>：整段音频离线转写、批量文档问答，前缀一次性到达，推测窗口为零，任何输入时推测都是纯开销。其二，<b>输出极短</b>：首包只含一两个 token 的响应（如唤醒词确认、单字指令），解码步数本就少，推测节省的绝对延迟低于校验与 KV 管理的固定成本。其三，<b>强约束或强随机</b>：结构化输出与高温采样使校验命中率趋零，无损前提也被削弱。</p>\n<p>判断清单可压缩为四个问题：前缀是否在等待期内持续增长；最终前缀对推测前缀的纠错率是否足够低；解码器是否暴露 RNG 与掩码状态以支持一致复用；未确认 KV 是否有独立的显存预算。四者缺一，迁移的净收益就应被质疑。表格给出迁移维度的对照：</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>需改动</th><th>主要代价</th><th>判断</th></tr></thead><tbody><tr><td>输入模态</td><td>触发器判据改为增量速率</td><td>触发次数下降，收益摊薄</td><td>语音优先，文本需实测</td></tr><tr><td>解码配置</td><td>RNG 与掩码状态随 KV 快照</td><td>采样器接口改造</td><td>确定性前向是硬前提</td></tr><tr><td>量化精度</td><td>推测与最终共用同一 kernel</td><td>吞吐让步换数值一致</td><td>NVFP4/FP8 下必须绑定</td></tr><tr><td>批调度</td><td>推测请求独立队列与 KV 上限</td><td>权重驻留显存翻倍</td><td>按会话密度权衡</td></tr><tr><td>推测长度</td><td>自适应 $K$ 反馈回路</td><td>调度器复杂度上升</td><td>纠错密集场景必需</td></tr></tbody></table>\n<p>规模上限的最终判断落在显存与命中率的联合约束上：未确认 KV 的硬上限决定了单实例可承载的并发推测会话数，而命中率衰减决定了每会话的有效 $K$。两者相乘给出实例级收益的天花板，超出这个天花板的并发增长只会把回退重算的频率推高、把首包延迟分位数拉长。工程上应把“推测命中率”与“未确认 KV 占用”作为一对联动指标纳入容量规划，而不是把推测当作一个可以无限叠加的加速开关。</p>\n\n<h3 id=\"paper-predgen-accelerated-inference-of-lar-2025-sec-57\">五十七 · 迁移到非流式负载与低命中率场景时的失效边界</h3>\n<p>这套方案的经济性完全建立在“输入时间窗口足够长、且识别增量与最终文本高度一致”这两个前提上。把 <span class=\"formula\">$$L_{\\text{eff}}=\\frac{T_{\\text{decode}}}{1+\\alpha\\cdot h}$$</span> 里的命中率 h 拆开看，它实际由两部分相乘：识别流在推测时刻给出的前缀与最终前缀的最长公共长度，以及该长度下推测 token 被接受的比例。一旦负载从流式语音换成一次性提交的批量文本（离线摘要、批量代码生成），输入阶段根本不存在可用的时间冗余，推测触发器的触发条件恒为空，系统退化为普通自回归解码，此时唯一还能保留的只有增量预填的 KV 复用逻辑，收益归零。迁移判断很直接：先测目标负载的“输入到达曲线”——若首 token 到达与末 token 到达的时间差小于单次推测解码的往返代价，就不要启用输入时推测，把算力留给连续批处理更划算。</p>\n<p>识别纠错是比命中率更硬的失效条件。流式 ASR 在用户说到一半时给出的前缀往往包含会被后续音频推翻的词（同音替换、专有名词后置修正），这类修正发生在前缀中段而非尾部时，最长公共前缀比对会在分歧点截断，命中长度 k 骤降，已解码的 token 与 KV 全部作废。代价不只是浪费：回退重算要从分歧点重新预填，而这段重算与用户话音结束后的正式解码争抢同一批 SM 与显存带宽，反而把首包延迟推高。工程上应把校验器从“逐 token 严格比对”放宽为“分歧点位置分级”——分歧落在最后 m 个 token 内时接受前缀、只丢弃尾部，分歧落在中段则直接放弃本次推测；m 的取值由 ASR 的纠错统计分布决定，而不是拍脑袋定。</p>\n<p>规模上限不在模型参数量，而在 KV 缓存与推测长度的乘积。设并发会话数为 B、单次推测长度为 K、层数为 L、KV 头维度为 d，则推测阶段额外驻留的 KV 元素量为 <span class=\"formula\">$$M_{\\text{spec}}=B\\cdot K\\cdot L\\cdot d\\cdot 2$$</span>（2 为 K 与 V）。在 Blackwell 的 HBM 容量约束下，B 与 K 是此消彼长的：提高 K 能摊薄每次推测的固定开销、提高单位时间命中 token 数，但线性吃掉并发容量；提高 B 则摊薄权重读取带宽、提升吞吐，却压缩了 K 的可用空间。低命中率区间里，K 增大带来的回退重算量与显存占用同步上升，净收益为负，这正是“推测长度越大越好”这一直觉的反例。迁移到 GB200 NVL72 这类机架级部署时，跨 GPU 的 KV 放置会让推测结果的复用多一次通信跳，命中收益要先扣掉这段 NVLink 往返再判断。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>需要改的部分</th><th>不适用/收益归零的条件</th></tr></thead><tbody><tr><td>离线批量文本</td><td>关闭推测触发器，仅留增量预填</td><td>无输入时间窗口，h→0</td></tr><tr><td>多语种/口音重识别</td><td>校验器分级容错、触发阈值上调</td><td>中段纠错频繁，k 被截断</td></tr><tr><td>NVFP4/FP8 量化部署</td><td>校验需在量化数值域内比对</td><td>低精度下前缀前向结果漂移，误判命中</td></tr><tr><td>高并发在线服务</td><td>K 与 B 联合调度，KV 分片</td><td>显存被推测 KV 挤占，批规模塌缩</td></tr></tbody></table>\n<p>量化部署是另一个容易被忽略的边界。校验依赖原模型对前缀的确定性前向，而在 NVFP4/FP8 下，同一前缀在不同 batch 组成、不同 kernel 选择下可能给出数值上不完全一致的 logits，逐 token 比对若用严格相等会误判为分歧、白白丢弃可复用的 KV；若放宽为容差比对，又可能在温度采样下引入分布偏移。正确做法是把随机数状态与量化 scale 一起纳入校验上下文：命中判定基于 token id 序列而非 logits，采样随机流按位置索引而非按调用次数推进，这样复用推测 token 时输出分布才与原模型对齐。温度采样下若不这样做，无损加速的前提就被破坏，迁移到生产环境时这是必须先验证的一条。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">PredGen: Accelerated </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Inference of Large…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · PredGen: Accelerated In… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出基线系统名称</td></tr><tr><td>主要结果</td><td>论文报告在实时语音交互场景下通过输入时推测降低首包延迟，具体加速比、延迟毫…</td></tr><tr><td>消融</td><td>材料未给出消融实验细节；可推断的关键变量为推测长度 K、触发阈值与命中率，…</td></tr><tr><td>局限</td><td>推测错误会引入额外预填与解码开销，长推测在低命中率下反而拖慢；流式识别增量…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-predgen-accelerated-inference-of-lar-2025 · 共 9 个片段</p>\n";break;}}})();
